pub const ParserOutputRange = struct {
    timed_audio: ?compiler.SelectedTimedAudio = null,
    definition_original: ?[]const u8 = null,
    nav_head_run_start: ?usize = null,
    definition_run_start: ?usize = null,
    literal_prefix: ?*const compiler.ObservedLiteralPrefix = null,
    static_paragraph_openings: []const usize = &.{},
    static_paragraph_original_prefix: []const u8 = "",
    static_example_openings: []const usize = &.{},
    static_example_original_prefix: []const u8 = "",
    observed_box_table_heading_root: bool = false,
    native_source_class_proof: ?*const NativeSourceClassProof = null,
    // Original full expansion, retained only by the normal exact-byte binder.
    // This is independent of prepared owner/page coordinates and root proofs.
    original_page: ?[]const u8 = null,
    source_element_projection: ?*const compiler.SourceElementProjection = null,
