pub const ObservedPreScope = struct {
    opening_start: usize,
    body_start: usize,
    body_end: usize,
    resume_at: usize,
    matched: bool,
    kind: FragmentPreContext.Kind = .pre,
    formatting: compiler.SpanFlags = .{},
    attributes: FormattingAttributes = .{},
    target: []const u8 = "",
    // Borrowed from the exact immutable page domain, not reconstructed markup.
    tag_name: []const u8 = "",
    link_quotes: ?compiler.LinkQuoteObservation = null,
    parent: ?usize = null,
    depth: usize = 1,
};
pub const PreparedBodySource = struct {
    source: []const u8,
    body_link_continuations: ?*const compiler.BodyLinkContinuations = null,
    missing: ?MissingText = null,
    fallbacks: Fallbacks,
};
pub fn prepareBodySourceAlloc(a: A, title: []const u8, source: []const u8) !PreparedBodySource {
    var renderer: compiler.Renderer = .{ .a = a, .context = .{ .title = title, .unclosed_fragment_trace = try unclosedFragmentTraceFromEnv(), .table_viewport_trace = try tableViewportTraceFromEnv() } };
    const prepared = try renderer.prepareBodySource(source);
    return .{ .source = prepared, .body_link_continuations = renderer.context.body_link_continuations, .fallbacks = renderer.fallbacks };
}
pub fn prepareBodySourceWithMissingAlloc(a: A, title: []const u8, source: MissingText) !PreparedBodySource {
    return prepareBodySourceInContextWithMissingAlloc(a, source, .{ .title = title,
        .unclosed_fragment_trace = try unclosedFragmentTraceFromEnv(), .table_viewport_trace = try tableViewportTraceFromEnv() }, null);
}
pub fn prepareBodySourceInContextWithMissingAlloc(a: A, source: MissingText, context: compiler.Context,
    projection: ?*const compiler.SourceElementProjection) !PreparedBodySource
{
    var renderer: compiler.Renderer = .{ .a = a, .context = context };
    renderer.context.unclosed_fragment_trace = context.unclosed_fragment_trace or try unclosedFragmentTraceFromEnv();
    renderer.context.table_viewport_trace = context.table_viewport_trace or try tableViewportTraceFromEnv();
    if (projection) |selected| if (context.local_link_targets) |targets| {
        if (selected.prepared.ptr == source.bytes.ptr and selected.prepared.len == source.bytes.len and
            selected.original.bytes.ptr == targets.source.ptr and selected.original.bytes.len == targets.source.len and
            !source.unknown and !source.lost_missing_range and source.generated_source == null)
            renderer.local_link_binding = .{ .projection = selected, .owner = source, .page_start = 0 };
    };
    bindContainerDisclosureProjection(&renderer, projection, source, 0);
    const prepared = try renderer.prepareBodySourceWithMissing(source);
    return .{ .source = prepared.bytes, .missing = prepared,
        .body_link_continuations = renderer.context.body_link_continuations, .fallbacks = renderer.fallbacks };
}
pub const PreObservation = struct {
    // Shared owned ancestry is deduplicated per probe element, not cloned per
    // scope/span. Its lifetime covers every resulting source fragment.
    text_ancestry: ?*std.heap.ArenaAllocator = null,
    scopes: []const ObservedPreScope,
    refused_link_openings: []const usize = &.{},
    unclosed_formatting: bool,
    pub fn deinitTextAncestry(self: PreObservation, a: A) void {
        if (self.text_ancestry) |arena| { arena.deinit(); a.destroy(arena); }
    }
};
pub fn observePreScopesAlloc(a: A, title: []const u8, source: []const u8, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: ReferenceDefinitions, poem_phase: ?*const PoemPhase) !PreObservation {
    return observePreScopesWithTextPaintAlloc(a, title, source, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, null);
}
pub fn observePreScopesWithTextPaintAlloc(a: A, title: []const u8, source: []const u8, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: ReferenceDefinitions, poem_phase: ?*const PoemPhase, text_styles: ?*const TableStyleProfile) !PreObservation {
    return observePreScopesSourceAlloc(a, title, source, null, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, text_styles, null, null);
}
// Prepared page bytes and all their provenance channels travel together. Raw
// callers retain the byte-only route and cannot inherit another source's proof.
pub fn observePreScopesWithTextPaintAndMissingAlloc(a: A, title: []const u8, source: MissingText, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: ReferenceDefinitions, poem_phase: ?*const PoemPhase, text_styles: ?*const TableStyleProfile) !PreObservation {
    return observePreScopesSourceAlloc(a, title, source.bytes, source, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, text_styles, null, null);
}
// The normal Builder can retain the existing full-page projection at this
// earlier scope-observation phase. Legacy callers keep their unknown root.
// No later owner fragment or byte-equal copy can lend this relationship.
pub fn observePreScopesWithSelectedPageAndMissingAlloc(a: A, title: []const u8, source: MissingText, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: ReferenceDefinitions, poem_phase: ?*const PoemPhase, text_styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, source_projection: ?*const compiler.SourceElementProjection) !PreObservation {
    return observePreScopesSourceAlloc(a, title, source.bytes, source, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, text_styles, figure_sizing, source_projection);
}

fn tracePreObservationBinding(renderer: *const compiler.Renderer, stage: []const u8, source: MissingText, styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, source_projection: ?*const compiler.SourceElementProjection) void {
    if (!renderer.context.table_viewport_trace) return;
    const observed = if (figure_sizing) |sizing| sizing.text_class_scope else null;
    std.debug.print("PREOBS_BIND_REFUSAL stage={s} current_bytes={d} projection={any} sizing={any} observed={any} profile={any} binding={any}\n", .{
        stage, source.bytes.len, source_projection != null, figure_sizing != null, observed != null,
        styles != null, renderer.source_element_binding != null,
    });
    if (source_projection) |projection| {
        std.debug.print("PREOBS_BIND_PROJECTION prepared_bytes={d} prepared_ptr_equal={any} original_bytes={d} selected={any}\n", .{
            projection.prepared.len, projection.prepared.ptr == source.bytes.ptr, projection.original.bytes.len, projection.observed_source != null,
        });
        if (observed) |held| {
            std.debug.print("PREOBS_BIND_ORIGINAL observed_bytes={d} original_ptr_equal={any} original_len_equal={any}\n", .{
                held.source.len, projection.original.bytes.ptr == held.source.ptr, projection.original.bytes.len == held.source.len,
            });
            if (projection.observed_source) |selected| std.debug.print("PREOBS_BIND_SELECTED scope_equal={any} source_ptr_equal={any} source_len_equal={any} selected_bytes={d}\n", .{
                selected.scope == held.scope, selected.source.ptr == held.source.ptr, selected.source.len == held.source.len, selected.source.len,
            });
        }
    }
    if (observed) |held| {
        std.debug.print("PREOBS_BIND_SCOPE observed_bytes={d} issued={any} literal_divs={d} profile_equal={any} root={any} complete_root={any}\n", .{
            held.source.len, held.scope.source_literal_divs_source != null, held.scope.source_literal_divs.len,
            held.scope.page_styles == styles, held.scope.page_style_root != null, held.scope.page_style_complete_root != null,
        });
        if (held.scope.source_literal_divs_source) |issued| std.debug.print("PREOBS_BIND_ISSUED bytes={d} ptr_equal={any} len_equal={any}\n", .{
            issued.len, issued.ptr == held.source.ptr, issued.len == held.source.len,
        });
    }
}

// This carries only the existing byte-copy source projection. It grants
// no ancestor/cascade authority and refuses generated or lost source ranges.
fn bindContainerDisclosureProjection(renderer: *compiler.Renderer,
    projection: ?*const compiler.SourceElementProjection, tracked: MissingText,
    page_start: usize) void
{
    renderer.container_disclosure_binding = null;
    const held = renderer.context.container_disclosures orelse return;
    const selected = projection orelse return;
    if (selected.original.bytes.ptr != held.source.ptr or selected.original.bytes.len != held.source.len or
        selected.original.unknown or selected.original.lost_missing_range or selected.original.generated_source != null or
        tracked.unknown or tracked.lost_missing_range or tracked.generated_source != null or
        page_start > selected.prepared.len or tracked.bytes.len > selected.prepared.len - page_start or
        !std.mem.eql(u8, tracked.bytes, selected.prepared[page_start..][0..tracked.bytes.len])) return;
    renderer.container_disclosure_binding = .{ .projection = selected, .owner = tracked, .page_start = page_start };
}

// Exact Phonos occurrence custody is independent of optional Figure sizing.
// This carries an existing insertion projection only. It does not set a
// content root, original-page capability, ancestor inventory, font or geometry.
fn preObservationPhonosPartCurrent(projection: *const compiler.SourceElementProjection,
    part: []const u8) bool
{
    if (part.len == 0) return false;
    const start = std.math.sub(usize, @intFromPtr(part.ptr),
        @intFromPtr(projection.original.bytes.ptr)) catch return false;
    if (start > projection.original.bytes.len or part.len > projection.original.bytes.len - start)
        return false;
    return projection.preparedRange(start, part.len) != null;
}

fn bindSelectedPhonosProjection(renderer: *compiler.Renderer, source: MissingText,
    styles: ?*const TableStyleProfile, source_projection: ?*const compiler.SourceElementProjection) void
{
    renderer.selected_phonos_source = null;
    const projection = source_projection orelse return;
    const profile = styles orelse return;
    if (profile.selected_phonos.len == 0 or source.unknown or source.lost_missing_range or
        source.generated_source != null or projection.original.unknown or
        projection.original.lost_missing_range or projection.original.generated_source != null or
        projection.prepared.ptr != source.bytes.ptr or projection.prepared.len != source.bytes.len)
        return;
    for (profile.selected_phonos) |selected| {
        if (!preObservationPhonosPartCurrent(projection, selected.source)) return;
        if (selected.decoration_source) |owner| {
            if (!preObservationPhonosPartCurrent(projection, owner)) return;
            const child_start = std.math.sub(usize, @intFromPtr(selected.source.ptr),
                @intFromPtr(owner.ptr)) catch return;
            if (child_start > owner.len or selected.source.len > owner.len - child_start) return;
        }
    }
    renderer.selected_phonos_source = .{ .projection = projection, .owner = source,
        .page_start = 0, .selected = profile.selected_phonos };
}

fn bindPreObservationSelectedPage(renderer: *compiler.Renderer, source: MissingText, styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, source_projection: ?*const compiler.SourceElementProjection) void {
    bindSelectedPhonosProjection(renderer, source, styles, source_projection);
    bindContainerDisclosureProjection(renderer, source_projection, source, 0);
    const projection = source_projection orelse {
        tracePreObservationBinding(renderer, "projection_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    const sizing = figure_sizing orelse {
        tracePreObservationBinding(renderer, "sizing_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    const observed = sizing.text_class_scope orelse {
        tracePreObservationBinding(renderer, "text_scope_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    const selected = projection.observed_source orelse {
        tracePreObservationBinding(renderer, "selected_source_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    const profile = styles orelse {
        tracePreObservationBinding(renderer, "profile_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    const issued = observed.scope.source_literal_divs_source orelse {
        tracePreObservationBinding(renderer, "issued_source_absent", source, styles, figure_sizing, source_projection);
        return;
    };
    if (selected.scope != observed.scope or selected.source.ptr != observed.source.ptr or selected.source.len != observed.source.len or
        projection.prepared.ptr != source.bytes.ptr or projection.prepared.len != source.bytes.len or
        projection.original.bytes.ptr != observed.source.ptr or projection.original.bytes.len != observed.source.len or
        issued.ptr != observed.source.ptr or issued.len != observed.source.len or observed.scope.source_literal_divs.len == 0 or
        observed.scope.page_styles != profile or observed.scope.page_style_root == null or observed.scope.page_style_complete_root == null) {
        if (renderer.context.table_viewport_trace) {
            const stage: []const u8 = if (selected.scope != observed.scope) "selected_scope_identity"
                else if (selected.source.ptr != observed.source.ptr or selected.source.len != observed.source.len) "selected_source_identity"
                else if (projection.prepared.ptr != source.bytes.ptr or projection.prepared.len != source.bytes.len) "prepared_source_identity"
                else if (projection.original.bytes.ptr != observed.source.ptr or projection.original.bytes.len != observed.source.len) "original_source_identity"
                else if (issued.ptr != observed.source.ptr or issued.len != observed.source.len) "issued_source_identity"
                else if (observed.scope.source_literal_divs.len == 0) "literal_divs_absent"
                else if (observed.scope.page_styles != profile) "page_profile_identity"
                else if (observed.scope.page_style_root == null) "page_root_absent"
                else "complete_root_absent";
            tracePreObservationBinding(renderer, stage, source, styles, figure_sizing, source_projection);
        }
        return;
    }
    // Reuse the ordinary fragment binder with a complete current page, whose
    // start and prepared bytes are the exact projection endpoint just checked.
    // Its consumers still validate original ranges, copies and taint locally.
    const fragment: SourceFragment = .{ .source = source.bytes, .original_start = 0, .missing = source,
        .parser_output_range = .{ .page = source.bytes, .start = 0, .prepared = source.bytes,
            .source_element_projection = projection } };
    renderer.content_root = .parser_output;
    renderer.context.table_styles = profile;
    renderer.context.figure_sizing = sizing;
    bindFragmentTextClassScope(renderer, fragment, source);
    if (renderer.source_element_binding == null)
        tracePreObservationBinding(renderer, "fragment_binding_absent", source, styles, figure_sizing, source_projection);
}

fn observePreScopesSourceAlloc(a: A, title: []const u8, source: []const u8, source_missing: ?MissingText, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: ReferenceDefinitions, poem_phase: ?*const PoemPhase, text_styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, source_projection: ?*const compiler.SourceElementProjection) !PreObservation {
    const observation_phase = consume_diagnostics.beginConsumePhase(.scope_observation);
    defer consume_diagnostics.endConsumePhase(observation_phase);
    const Collector = struct {
        a: A,
        source: []const u8,
        renderer: ?*const compiler.Renderer = null,
        text_ancestry: ?*std.heap.ArenaAllocator = null,
        // Keys belong to the single live, never-reset probe arena below. The
        // map is destroyed before that arena and never escapes this function;
        // no later probe generation can reuse a key in this cache.
        text_elements: std.AutoHashMapUnmanaged(*const TextElement, *const TextElement) = .empty,
        scopes: std.ArrayList(ObservedPreScope) = .empty,
        refused_link_openings: std.ArrayList(usize) = .empty,
        fn ownedTextElement(self: *@This(), source_element: ?*const TextElement) std.mem.Allocator.Error!?*const TextElement {
            const original = source_element orelse return null;
            if (self.text_elements.get(original)) |owned| return owned;
            const parent = try self.ownedTextElement(original.parent);
            if (self.text_ancestry == null) {
                const arena = try self.a.create(std.heap.ArenaAllocator);
                arena.* = std.heap.ArenaAllocator.init(self.a);
                self.text_ancestry = arena;
            }
            const ancestry_allocator = self.text_ancestry.?.allocator();
            const owned = try ancestry_allocator.create(TextElement);
            const start = @intFromPtr(self.source.ptr);
            owned.* = .{
                .tag = try ancestry_allocator.dupe(u8, original.tag),
                .classes = try ancestry_allocator.dupe(u8, original.classes),
                .id = try ancestry_allocator.dupe(u8, original.id),
                .parent = parent,
                // Retain only identity within the immutable caller page. A
                // probe-arena address must never be a future deduplication key.
                .source_key = if (original.source_key >= start and original.source_key - start < self.source.len) original.source_key else 0,
            };
            try self.text_elements.put(self.a, original, owned);
            return owned;
        }
        fn enter(raw: ?*anyopaque, domain: []const u8, origin: ?usize, opening_start: usize, body_start: usize, body_end: usize, resume_at: usize, matched: bool, kind: FragmentPreContext.Kind, formatting: compiler.SpanFlags, target: []const u8, attributes: FormattingAttributes) compiler.Error!void {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            const base = origin orelse return;
            if (base > self.source.len or domain.len > self.source.len - base or
                domain.ptr != self.source[base..].ptr)
                return error.InvalidPreContext;
            if (kind == .refused_link) {
                if (opening_start > domain.len or domain.len - opening_start < 2 or
                    domain[opening_start] != '[' or domain[opening_start + 1] != '[' or
                    body_start != opening_start or body_end != opening_start or resume_at != opening_start or
                    matched or target.len != 0 or !std.meta.eql(formatting, compiler.SpanFlags{}))
                    return error.InvalidPreContext;
                try self.refused_link_openings.append(self.a, base + opening_start);
                return;
            }
            if (opening_start >= body_start or body_start > body_end or body_end > resume_at or resume_at > domain.len)
                return error.InvalidPreContext;
            const hidden_tag = if (kind == .hidden or kind == .css_block) blk: {
                const tag = blobs.wikitext_syntax.tagAt(domain, opening_start) orelse return error.InvalidPreContext;
                if (!matched or tag.closing or tag.self_closing or tag.end != body_start or target.len != 0) return error.InvalidPreContext;
                if (kind == .css_block) {
                    const class_authority = tag.attr("class") != null and attributes.css_ancestor_classes.len != 0;
                    const alignment_authority = (tag.attr("style") != null or tag.attr("align") != null) and attributes.text_align != null;
                    const title_authority = compiler.hasAuthoredTooltipTitle(tag) and attributes.tooltip_set;
                    var relative_authority = false;
                    if (attributes.relative_context_policy_present) {
                        const css = (try compiler.authoredStyleAttributeAlloc(self.a, tag)) orelse "";
                        relative_authority = try @import("table_style_profile.zig").hasRelativeContextDeclarationsAlloc(self.a, css);
                        if (!relative_authority) if (self.renderer) |renderer| {
                            const profile = renderer.context.text_paint_styles orelse renderer.context.table_styles;
                            if (profile) |selected| if (attributes.text_element) |node| {
                                if (node.source_key == @intFromPtr(tag.name.ptr) and std.ascii.eqlIgnoreCase(node.tag, tag.name))
                                    relative_authority = try selected.relativeContextPolicyPresentIn(self.a, node, css);
                            };
                        };
                    }
                    const fragmentation_authority = attributes.column_fragmentation_policy_present and
                        try @import("table_style_profile.zig").hasColumnFragmentationDeclarationsAlloc(self.a,
                            (try compiler.authoredStyleAttributeAlloc(self.a, tag)) orelse "");
                    const collapse_authority = attributes.table_inheritance_scoped and attributes.table_collapse != null and
                        try @import("table_style_profile.zig").hasBorderCollapseDeclarationsAlloc(self.a, (try compiler.authoredStyleAttributeAlloc(self.a, tag)) orelse "");
                    if (!tag.is("div") or (!class_authority and !alignment_authority and !title_authority and !collapse_authority and !fragmentation_authority and !relative_authority)) return error.InvalidPreContext;
                }
                const pair = (if (kind == .css_block)
                    compiler.cssBlockScopePair(domain, tag)
                else
                    blobs.wikitext_syntax.matchingTag(domain, tag)) orelse return error.InvalidPreContext;
                if (pair.inner_end != body_end or pair.end != resume_at) return error.InvalidPreContext;
                break :blk tag.name;
            } else "";
            const absolute_open = base + opening_start;
            var parent: ?usize = if (self.scopes.items.len == 0) null else self.scopes.items.len - 1;
            if (parent) |previous| if (self.scopes.items[previous].opening_start >= absolute_open) {
                const prior = self.scopes.items[previous];
                // Coordinates belong to this exact observed prepared source,
                // never an inferred original-page or DOM position.
                const current_end = @min(self.source.len, absolute_open + @min(@as(usize, 96), self.source.len - absolute_open));
                const prior_end = @min(self.source.len, prior.opening_start + @min(@as(usize, 96), self.source.len - prior.opening_start));
                var current_hex: [192]u8 = undefined;
                var prior_hex: [192]u8 = undefined;
                const alphabet = "0123456789abcdef";
                for (self.source[absolute_open..current_end], 0..) |byte, index| {
                    current_hex[index * 2] = alphabet[byte >> 4]; current_hex[index * 2 + 1] = alphabet[byte & 15];
                }
                for (self.source[prior.opening_start..prior_end], 0..) |byte, index| {
                    prior_hex[index * 2] = alphabet[byte >> 4]; prior_hex[index * 2 + 1] = alphabet[byte & 15];
                }
                consume_diagnostics.logLine("presentation scope_order source_bytes={d} previous_kind={s} previous_open={d} previous_body={d} previous_end={d} previous_resume={d} current_kind={s} current_open={d} current_body={d} current_end={d} current_resume={d} current_domain_base={d} current_domain_bytes={d} previous_hex={s} current_hex={s}", .{
                    self.source.len, @tagName(prior.kind), prior.opening_start, prior.body_start, prior.body_end, prior.resume_at,
                    @tagName(kind), absolute_open, base + body_start, base + body_end, base + resume_at, base, domain.len,
                    prior_hex[0 .. (prior_end - prior.opening_start) * 2], current_hex[0 .. (current_end - absolute_open) * 2],
                });
                return error.InvalidPreContext;
            };
            while (parent) |index| {
                const candidate = self.scopes.items[index];
                if (absolute_open >= candidate.body_start and base + resume_at <= candidate.body_end) break;
                parent = candidate.parent;
            }
            const depth = if (parent) |index| self.scopes.items[index].depth + 1 else 1;
            // This event is emitted before descending into its body. Bound the
            // stored ancestry by the actual renderer call depth, whose entry
            // already enforces the renderer max_depth limit.
            if (depth > self.renderer.?.body_depth) return error.InvalidPreContext;
            const link_quotes = if (kind == .link)
                self.renderer.?.link_quote_observation orelse return error.InvalidPreContext
            else
                null;
            const owned_target = try self.a.dupe(u8, target);
            errdefer self.a.free(owned_target);
            const owned_classes = try self.a.dupe(u8, attributes.classes);
            errdefer self.a.free(owned_classes);
            const owned_css_classes = try self.a.dupe(u8, attributes.css_ancestor_classes);
            errdefer self.a.free(owned_css_classes);
            const owned_language = try self.a.dupe(u8, attributes.language);
            errdefer self.a.free(owned_language);
            const owned_direction = try self.a.dupe(u8, attributes.direction);
            errdefer self.a.free(owned_direction);
            const owned_captured_direction = if (attributes.captured_direction) |value| try self.a.dupe(u8, value) else null;
            errdefer if (owned_captured_direction) |value| self.a.free(value);
            const owned_explanation = try self.a.dupe(u8, attributes.explanation);
            errdefer self.a.free(owned_explanation);
            const owned_tooltip = if (attributes.tooltip) |advice| try self.a.dupe(u8, advice) else null;
            errdefer if (owned_tooltip) |advice| self.a.free(advice);
            const owned_foreground = if (attributes.foreground) |color| try self.a.dupe(u8, color) else null;
            errdefer if (owned_foreground) |color| self.a.free(color);
            const owned_family = ownFontFamily(self.a, attributes.font_family) catch |err| return switch (err) {
                error.InvalidPresentation => error.UncompiledPresentation,
                error.OutOfMemory => error.OutOfMemory,
            };
            errdefer freeFontFamily(self.a, owned_family);
            const owned_text_element = try self.ownedTextElement(attributes.text_element);
            try self.scopes.append(self.a, .{
                .opening_start = absolute_open,
                .body_start = base + body_start,
                .body_end = base + body_end,
                .resume_at = base + resume_at,
                .matched = matched,
                .kind = kind,
                .formatting = formatting,
                .attributes = .{ .native_inline_motion = .unknown, .text_element = owned_text_element, .relative_context_policy_present = attributes.relative_context_policy_present, .column_fragmentation_policy_present = attributes.column_fragmentation_policy_present, .table_collapse = attributes.table_collapse, .table_inheritance_scoped = attributes.table_inheritance_scoped, .text_align = attributes.text_align, .classes = owned_classes, .css_ancestor_classes = owned_css_classes, .role = attributes.role, .relation_note = attributes.relation_note, .language = owned_language, .direction = owned_direction, .captured_direction = owned_captured_direction, .explanation = owned_explanation, .explanation_set = attributes.explanation_set, .tooltip = owned_tooltip, .tooltip_set = attributes.tooltip_set, .foreground = owned_foreground, .foreground_set = attributes.foreground_set, .font_scale = attributes.font_scale, .font_scale_basis = attributes.font_scale_basis, .font_features = attributes.font_features, .font_family = owned_family, .font_scale_set = attributes.font_scale_set, .font_size_unknown = attributes.font_size_unknown },
                .target = owned_target,
                .tag_name = hidden_tag,
                .link_quotes = link_quotes,
                .parent = parent,
                .depth = depth,
            });
        }
    };
    var collected: Collector = .{ .a = a, .source = source };
    errdefer {
        for (collected.scopes.items) |scope| {
            a.free(scope.target);
            a.free(scope.attributes.classes);
            a.free(scope.attributes.css_ancestor_classes);
            a.free(scope.attributes.language);
            a.free(scope.attributes.direction);
            if (scope.attributes.captured_direction) |value| a.free(value);
            a.free(scope.attributes.explanation);
            if (scope.attributes.tooltip) |advice| a.free(advice);
            if (scope.attributes.foreground) |color| a.free(color);
            freeFontFamily(a, scope.attributes.font_family);
        }
        if (collected.text_ancestry) |owned| { owned.deinit(); a.destroy(owned); }
        collected.scopes.deinit(a);
        collected.refused_link_openings.deinit(a);
    }
    // The probe's blocks, spans, references and media never escape this arena.
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    defer collected.text_elements.deinit(a);
    var renderer: compiler.Renderer = .{
        .a = arena.allocator(),
        .body_missing = source_missing,
        .context = .{
            .title = title,
            .text_paint_styles = text_styles,
            .observe_structure_only = true,
            .unclosed_fragment_trace = try unclosedFragmentTraceFromEnv(),
            .table_viewport_trace = try tableViewportTraceFromEnv(),
            .language = "English",
            .link_trail = link_trail,
            .namespace_catalog = namespace_catalog,
            .behavior_switches = behavior_switches,
            .image_options = image_options,
            .poem_phase = poem_phase,
            .citations = reference_context.citations,
            .content_conversion = reference_context.content_conversion,
            .display_title_precedence = reference_context.display_title_precedence,
            .normal_title_defaults = reference_context.normal_title_defaults,
            .container_disclosures = reference_context.container_disclosures,
            .local_link_targets = reference_context.local_link_targets,
            .body_link_continuations = reference_context.body_link_continuations,
            .external_links_prepared = reference_context.citations != null,
        },
    };
    renderer.page_reference_definitions = reference_context.items;
    if (source_missing) |tracked| bindPreObservationSelectedPage(&renderer, tracked, text_styles, figure_sizing, source_projection);
    collected.renderer = &renderer;
    _ = try renderer.renderBodyWithPreObserver(source, .{ .ctx = &collected, .enter = Collector.enter });
    // A truncated probe cannot establish a complete page scope map.
    if (renderer.truncated or renderer.fallbacks.render_limit) return error.RenderLimit;
    std.mem.sort(usize, collected.refused_link_openings.items, {}, std.sort.asc(usize));
    var unique: usize = 0;
    for (collected.refused_link_openings.items) |opening| {
        if (unique == 0 or collected.refused_link_openings.items[unique - 1] != opening) {
            collected.refused_link_openings.items[unique] = opening;
            unique += 1;
        }
    }
    collected.refused_link_openings.items = collected.refused_link_openings.items[0..unique];
    const refused_link_openings = try collected.refused_link_openings.toOwnedSlice(a);
    errdefer a.free(refused_link_openings);
    return .{ .text_ancestry = collected.text_ancestry, .scopes = try collected.scopes.toOwnedSlice(a), .refused_link_openings = refused_link_openings, .unclosed_formatting = renderer.fallbacks.unclosed_formatting };
}

fn freeFontFamily(a: A, value: ?types.ContainerFontFamily) void {
    if (value) |family| switch (family) {
        .sans_serif => {},
        .stack => |stack| {
            for (stack.names) |name| a.free(name);
            a.free(stack.names);
        },
    };
}
fn ownFontFamily(a: A, value: ?types.ContainerFontFamily) !?types.ContainerFontFamily {
    const family = value orelse return null;
    if (!types.validContainerFontFamily(family)) return error.InvalidPresentation;
    switch (family) {
        .sans_serif => return family,
        .stack => |stack| {
            const names = try a.alloc([]const u8, stack.names.len);
            var initialized: usize = 0;
            errdefer {
                for (names[0..initialized]) |name| a.free(name);
                a.free(names);
            }
            for (stack.names, names) |source, *destination| {
                destination.* = try a.dupe(u8, source);
                initialized += 1;
            }
            return .{ .stack = .{ .names = names, .fallback = stack.fallback } };
        },
    }
}

