    anchor_fallback: []const u8 = "",
    heading_source_offset: ?usize = null,
    heading_authored_id: []const u8 = "",
    title_depth: u8 = 0,
    title_list_path: []const u8 = "",
    title_spans: []const compiler.Span = &.{},
    level: u8,
    title: []const u8,
    blocks: []const compiler.Block,
};
const Work = struct {
    sections: []const WorkSection,
    page_html_openings: []const usize = &.{},
    page_wiki_openings: []const usize = &.{},
    page_wiki_content_openings: []const usize = &.{},
    page_wiki_all_openings: []const usize = &.{},
    page_wiki_rule_openings: []const usize = &.{},
    page_root_wiki_table_openings: []const usize = &.{},
    page_static_paragraph_openings: []const usize = &.{},
    page_static_example_openings: []const usize = &.{},
    page_top_level_wiki_table_openings: []const usize = &.{},
    references: []const compiler.Reference,
    media: []const compiler.media_types.Media,
    media_caption_spans: []const []const compiler.Span,
    rendered_templates: usize,
    unresolved_templates: usize,
    fallbacks: Fallbacks,
};

// One authoritative cell branch, one shared collection budget and table depth
// for each document pass. Cell headings remain Blocks throughout these visits.
const CompilerWalk = struct {
    // Semantic traversal alone does not certify native geometry.
    require_native_inline_boxes: bool = false,
    remaining: usize = 1 << 20,
    content_depth: usize = 0,
    typed_bidi_depth: usize = 0,
    ruby_depth: usize = 0,

    fn take(self: *CompilerWalk, count: usize) !void {
        if (count > self.remaining) return error.InvalidPresentation;
        self.remaining -= count;
    }
    fn spans(self: *CompilerWalk, context: anytype, values: []const compiler.Span) anyerror!void {
        return self.spansIn(context, values, .ordinary);
    }
    fn inlineBoxSpans(self: *CompilerWalk, context: anytype,
        group: *const types.InlineBoxGroup(compiler.Span)) anyerror!void
    {
        if (!types.inlineBoxHasOverlayContent(group.*))
            return self.spansIn(context, group.spans, .ordinary);
        // The shared validator proved ordered child boundaries. Keep source text
        // interleaved without granting out-of-flow children normal-flow geometry.
        var at: usize = 0;
        for (group.overlays) |overlay| if (overlay.content) |content| {
            const boundary: usize = content.before_child;
            if (boundary > at) try self.spansIn(context, group.spans[at..boundary], .ordinary);
            if (self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
            self.content_depth += 1;
            defer self.content_depth -= 1;
            try self.spansIn(context, content.spans, .ordinary);
            at = boundary;
        };
        if (at < group.spans.len) try self.spansIn(context, group.spans[at..], .ordinary);
    }
    fn spansIn(self: *CompilerWalk, context: anytype, values: []const compiler.Span,
        comptime part: enum { ordinary, gap, body, owned_flow_run }) anyerror!void
    {
        if (self.typed_bidi_depth != 0) for (values) |span| {
            if (span.captured_bidi_scope != null or span.generated_bidi_boundary) return error.InvalidPresentation;
        };
        try self.take(values.len);
        var native_obligation = self.require_native_inline_boxes and compiler.hasInlineBoxParagraphObligation(values);
        // Empty-overlay groups include the static carrier. Their structural
        // obligation survives copies, with no removable build-only marker.
        for (values) |span| if (span.inline_box_group) |group| {
            if (group.overlays.len == 0) native_obligation = true;
        };
        if (native_obligation and part != .owned_flow_run) {
            if (self.typed_bidi_depth != 0 or part != .ordinary) return error.UncompiledPresentation;
            try compiler.validateInlineBoxParagraph(values);
        }
        try context.spans(values);
        if (comptime part == .gap) {
            if (!types.validRubyGap(values)) return error.InvalidPresentation;
        } else if (comptime part == .body) {
            for (values) |span| if (!types.validRubyBodyChild(span)) return error.InvalidPresentation;
        }
        for (values) |span| if (span.inline_action_group) |group| {
            if (part == .gap or self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
            try types.validateInlineActionGroupTree(span, self.content_depth, self.ruby_depth);
            self.content_depth += 1;
            defer self.content_depth -= 1;
            try self.spansIn(context, group.spans, .body);
        };
        for (values) |span| if (span.inline_box_group) |group| {
            if (part == .gap or self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
            try types.validateInlineBoxGroupTree(span, self.content_depth, self.ruby_depth);
            // Each overlay owner and its actual body share the document budget.
            // Inline boxes and overlay bodies do not consume Ruby depth.
            try self.take(group.overlays.len);
            self.content_depth += 1;
            defer self.content_depth -= 1;
            try self.inlineBoxSpans(context, group);
        };
        for (values) |span| if (span.inline_padding_group) |group| {
            if (part == .gap or self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
            try types.validateInlinePaddingGroupTree(span, self.content_depth, self.ruby_depth);
            self.content_depth += 1;
            defer self.content_depth -= 1;
            try self.spansIn(context, group.spans, .body);
        };
        for (values) |span| if (span.ruby) |ruby| {
            if (!types.validRubyOwner(span) or self.ruby_depth >= types.max_ruby_depth or
                self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
            try self.take(ruby.segments.len);
            for (ruby.segments) |segment| {
                try self.take(segment.bases.len);
                try self.take(segment.annotations.len);
                for (segment.bases) |base| {
                    try self.take(1);
                    if (!types.validRubyOwnerContext(base.owner)) return error.InvalidPresentation;
                }
                for (segment.annotations) |annotation| {
                    try self.take(1);
                    if (!types.validRubyOwnerContext(annotation.owner)) return error.InvalidPresentation;
                }
            }
            if (!types.validRuby(ruby.*)) return error.InvalidPresentation;
            self.ruby_depth += 1;
            self.content_depth += 1;
            defer self.ruby_depth -= 1;
            defer self.content_depth -= 1;
            // Validation and semantic observers see every actual child,
            // including auto-hidden/empty readings and explicit fallback runs.
            // Generated terminal parentheses are not stored source children.
            for (ruby.segments) |segment| {
                try self.spansIn(context, segment.gap_before, .gap);
                for (segment.bases) |base| {
                    try self.spansIn(context, base.gap_before, .gap);
                    try self.spansIn(context, base.spans, .body);
                }
                for (segment.annotations) |annotation| {
                    try self.spansIn(context, annotation.gap_before, .gap);
                    try self.spansIn(context, annotation.fallback_before, .body);
                    try self.spansIn(context, annotation.spans, .body);
                    try self.spansIn(context, annotation.fallback_after, .body);
                }
            }
        };
    }
    fn references(self: *CompilerWalk, context: anytype, values: []const compiler.Reference) anyerror!void {
        try self.take(values.len);
        for (values) |reference| {
            if (reference.blocks) |ordered_blocks| {
                if (reference.spans.len != 0) return error.InvalidPresentation;
                try self.blocks(context, ordered_blocks, 0);
            } else try self.spans(context, reference.spans);
        }
    }
    fn captionBlocks(self: *CompilerWalk, context: anytype, values: []const compiler.Block, table_depth: usize) anyerror!void {
        if (self.content_depth >= 16) return error.InvalidPresentation;
        self.content_depth += 1;
        defer self.content_depth -= 1;
        try self.blocks(context, values, table_depth);
    }
    fn figure(self: *CompilerWalk, context: anytype, value: *compiler.Figure, table_depth: usize) anyerror!void {
        const image: *[1]compiler.Span = @ptrCast(value.content.spanPtr());
        try self.spans(context, image);
        if (value.caption_blocks) |children| {
            if (value.caption.len != 0) return error.InvalidPresentation;
            try self.captionBlocks(context, children, table_depth);
        } else try self.spans(context, value.caption);
    }
    fn flow(self: *CompilerWalk, context: anytype, parts: []const compiler.FlowPart, table_depth: usize) anyerror!void {
        return self.flowInBlock(context, parts, table_depth, null);
    }
    fn flowInBlock(self: *CompilerWalk, context: anytype, parts: []const compiler.FlowPart,
        table_depth: usize, owner: ?*const compiler.Block) anyerror!void
    {
        if (self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
        self.content_depth += 1;
        defer self.content_depth -= 1;
        try self.take(parts.len);
        for (@constCast(parts)) |*part| {
            if (@hasDecl(@TypeOf(context.*), "flowPart")) try context.flowPart(part.*);
            switch (part.kind) {
                .@"inline" => {
                    if (part.figure != null or part.scope != null) return error.InvalidPresentation;
                    if (compiler.hasInlineBoxParagraphObligation(part.spans)) {
                        if (self.typed_bidi_depth != 1) return error.UncompiledPresentation;
                        try compiler.validateInlineBoxFlowRun(owner orelse return error.UncompiledPresentation, part.spans);
                        try self.spansIn(context, part.spans, .owned_flow_run);
                    } else try self.spans(context, part.spans);
                },
                .figure => {
                    if (part.spans.len != 0 or part.scope != null) return error.InvalidPresentation;
                    if (part.figure) |*value| try self.figure(context, value, table_depth) else return error.InvalidPresentation;
                },
                .scope => {
                    if (part.spans.len != 0 or part.figure != null) return error.InvalidPresentation;
                    const scope = part.scope orelse return error.InvalidPresentation;
                    if (!types.validBidiScopeHeader(scope)) return error.InvalidPresentation;
                    self.typed_bidi_depth += 1;
                    defer self.typed_bidi_depth -= 1;
                    try self.flowInBlock(context, scope.parts, table_depth, owner);
                },
            }
        }
    }
    fn blocks(self: *CompilerWalk, context: anytype, values: []const compiler.Block, table_depth: usize) anyerror!void {
        try self.take(values.len);
        for (@constCast(values)) |*block| {
            try context.block(block);
            if (types.contentBox(block.*)) |container| {
                const valid_owner = if (block.description_body != null) types.validDescriptionOwner(block.*) else types.validContainerContext(block.*);
                if (block.description_body != null) try self.take(1);
                if (!valid_owner or !types.validContainerHeader(container))
                    return error.InvalidPresentation;
                if (self.content_depth >= types.max_content_depth) return error.InvalidPresentation;
                self.content_depth += 1;
                defer self.content_depth -= 1;
                try self.blocks(context, container.blocks, table_depth);
                continue;
            }
            if (block.kind == .container) return error.InvalidPresentation;
            if (block.figure) |*figure_value| {
                if (block.spans.len != 0 or block.flow != null) return error.InvalidPresentation;
                try self.figure(context, figure_value, table_depth);
            }
            if (block.flow) |parts| {
                if (block.spans.len != 0) return error.InvalidPresentation;
                try self.flowInBlock(context, parts, table_depth, block);
            }
            try self.spans(context, block.spans);
            if (block.table) |child_table| try self.table(context, child_table, table_depth + 1);
        }
    }
    fn table(self: *CompilerWalk, context: anytype, value: compiler.Table, table_depth: usize) anyerror!void {
        if (table_depth > types.max_table_depth) return error.InvalidPresentation;
        if (!types.validTableViewportHeaders(value.geometry, value.style, value.block_viewport, value.float_viewport)) return error.InvalidPresentation;
        var has_cells = false; for (value.rows) |row| if (row.cells.len != 0) { has_cells = true; break; };
        if (!types.validTableFloatViewportContent(value.float_viewport, value.caption.len, value.caption_blocks != null, has_cells)) return error.InvalidPresentation;
        if (value.caption_blocks) |children| {
            if (value.caption.len != 0) return error.InvalidPresentation;
            try self.captionBlocks(context, children, table_depth);
        } else try self.spans(context, value.caption);
        try self.take(value.rows.len);
        for (value.rows) |row| {
            try self.take(row.cells.len);
            for (row.cells) |cell| {
                if (cell.blocks) |ordered_blocks| {
                    if (cell.spans.len != 0 or cell.nested_table != null) return error.InvalidPresentation;
                    try self.blocks(context, ordered_blocks, table_depth);
                } else {
                    try self.spans(context, cell.spans);
                    if (cell.nested_table) |child| try self.table(context, child, table_depth + 1);
                }
            }
        }
    }

};

const RebaseHeadingOffsets = struct {
    base: usize,
    fn spans(_: *@This(), _: []const compiler.Span) anyerror!void {}
    fn block(self: *@This(), value: *compiler.Block) anyerror!void {
        if (value.heading_source_offset) |offset|
            value.heading_source_offset = std.math.add(usize, self.base, offset) catch return error.InvalidHeadingProjection;
    }
};

const ObserveHeadings = struct {
    a: A,
    registry: *heading_ids.Registry,
    result: *std.ArrayList(HeadingAnchor),
    fn spans(_: *@This(), _: []const compiler.Span) anyerror!void {}
    fn add(self: *@This(), source_offset: ?usize, authored_id: []const u8, values: []const compiler.Span) !void {
        const offset = source_offset orelse return error.InvalidHeadingProjection;
        var report: Fallbacks = .{};
        try validateSpans(self.a, values, &report);
        const text = try compiler.plainText(self.a, values);
        const identity = if (authored_id.len != 0) try self.registry.authoredIds(self.a, authored_id) else try self.registry.headingIds(self.a, text);
        try self.result.append(self.a, .{ .source_offset = offset, .anchor = identity.anchor, .anchor_fallback = identity.anchor_fallback });
    }
    fn block(self: *@This(), value: *compiler.Block) anyerror!void {
        if (value.kind == .heading) try self.add(value.heading_source_offset, value.heading_authored_id, value.spans);
    }
};

const AssignHeadings = struct {
    a: A,
    registry: *heading_ids.Registry,
    observation: ?*const HeadingObservation,
    projection: []const HeadingSourceRange,
    fn spans(_: *@This(), _: []const compiler.Span) anyerror!void {}
    fn identity(self: *@This(), source_offset: ?usize, authored_id: []const u8, text: []const u8) !heading_ids.Ids {
        if (self.observation) |observation| {
            const local = source_offset orelse return error.InvalidHeadingProjection;
            var page: ?usize = null;
            for (self.projection) |range| {
                if (local >= range.owner_start and local - range.owner_start < range.len) {
                    page = std.math.add(usize, range.page_start, local - range.owner_start) catch return error.InvalidHeadingProjection;
                    break;
                }
            }
            const offset = page orelse return error.InvalidHeadingProjection;
            for (observation.items) |item| if (item.source_offset == offset)
                return .{ .anchor = item.anchor, .anchor_fallback = item.anchor_fallback };
            return error.InvalidHeadingProjection;
        }
        return if (authored_id.len != 0) try self.registry.authoredIds(self.a, authored_id) else try self.registry.headingIds(self.a, text);
    }
    fn block(self: *@This(), value: *compiler.Block) anyerror!void {
        if (value.kind != .heading) return;
        const ids = try self.identity(value.heading_source_offset, value.heading_authored_id, try compiler.plainText(self.a, value.spans));
        value.anchor = ids.anchor;
        value.anchor_fallback = ids.anchor_fallback;
    }
};

const ValidateCompilerSpans = struct {
    a: A,
    source_anchors: ?*heading_ids.Registry = null,
    fallbacks: ?*Fallbacks,
    fn figure(self: *@This(), value: compiler.Figure) anyerror!void {
        errdefer if (self.fallbacks) |report| { report.unrepresented_figure = true; };
        const content_span = value.content.span();
        if (!types.validFigureGeometry(value) or value.deferred_geometry != null or content_span.pending_figure != null or content_span.pending_bidi_scope != null or content_span.pending_container != null or
            (value.caption_blocks != null and value.caption.len != 0)) return error.UncompiledPresentation;
        switch (value.content) {
            .image => |content| {
                const image = content.span.image orelse return error.UncompiledPresentation;
                if (content.span.text.len != 0 or !types.validFigureSizingContext(value.format, content.sizing, image.width_px, image.height_px)) return error.UncompiledPresentation;
            },
            .missing => |content| {
                if (content.label.image != null or content.label.text.len == 0 or value.map_fallback != null or
                    !types.validStyleLength(content.width) or content.width.value == 0 or
                    !types.validStyleLength(content.line_height) or content.line_height.value == 0) return error.UncompiledPresentation;
            },
        }
    }
    fn flowPart(self: *@This(), part: compiler.FlowPart) anyerror!void {
        errdefer if (self.fallbacks) |report| { report.unrepresented_figure = true; };
        switch (part.kind) {
            .@"inline" => if (part.figure != null or part.scope != null) return error.UncompiledPresentation,
            .figure => {
                if (part.spans.len != 0 or part.scope != null) return error.UncompiledPresentation;
                try self.figure(part.figure orelse return error.UncompiledPresentation);
            },
            .scope => {
                if (part.spans.len != 0 or part.figure != null) return error.UncompiledPresentation;
                if (!types.validBidiScopeHeader(part.scope orelse return error.UncompiledPresentation)) return error.UncompiledPresentation;
            },
        }
    }
    fn block(self: *@This(), value: *compiler.Block) anyerror!void {
        const kind = std.meta.stringToEnum(types.BlockKind, @tagName(value.kind)) orelse return error.UncompiledPresentation;
        if (self.source_anchors) |anchors| {
            if (kind != .heading and value.anchor.len != 0)
                try anchors.reserveUniqueExisting(self.a, value.anchor);
        }
        if (value.figure) |figure_value| {
            errdefer if (self.fallbacks) |report| { report.unrepresented_figure = true; };
            if (value.spans.len != 0 or value.flow != null or !types.validFigureContext(kind, value.depth, value.table != null, value.feature != null, value.style != null, value.list_path)) return error.UncompiledPresentation;
            try self.figure(figure_value);
        }
        if (value.flow) |parts| {
            errdefer if (self.fallbacks) |report| { report.unrepresented_figure = true; };
            if (value.spans.len != 0 or !types.validFlowContext(kind, value.depth, value.table != null, value.feature != null, value.figure != null, value.list_path)) return error.UncompiledPresentation;
            for (parts) |part| try self.flowPart(part);
        }
    }
    fn spans(self: *@This(), values: []const compiler.Span) anyerror!void {
        try validateSpansFlat(self.a, values, self.fallbacks);
    }
};

const Builder = struct {
    heading_style: ?types.SectionHeadingStyle = null,
    expected_heading_pair: @FieldType(compiler.Block,"expected_heading_pair") = null,
    is_heading: bool = false,
    heading_source_offset: ?usize = null,
    heading_authored_id: []const u8 = "",
    title_depth: u8 = 0,
    title_list_path: []const u8 = "",
    title_spans: []const compiler.Span = &.{},
    a: A,
    renderer: *compiler.Renderer,
    sections: std.ArrayList(WorkSection) = .empty,
    title: []const u8,
    level: u8 = 2,
    started: bool = false,

    fn flush(self: *Builder, blocks: []const compiler.Block) !void {
        if (!self.started) return;
        try self.sections.append(self.a, .{
            .level = self.level,
            .title = self.title,
            .is_heading = self.is_heading,
            .heading_style = self.heading_style,
            .expected_heading_pair = self.expected_heading_pair,
            .heading_source_offset = self.heading_source_offset,
            .heading_authored_id = self.heading_authored_id,
            .title_spans = self.title_spans,
            .title_depth = self.title_depth,
            .title_list_path = self.title_list_path,
            .blocks = blocks,
        });
    }

    fn render(self: *Builder, source: []const u8) !void {
        try self.renderWithMissing(MissingText.untracked(source));
    }
    fn renderWithMissing(self: *Builder, source: MissingText) !void {
        try self.consume(try self.renderer.renderBodyWithMissing(source));
    }

    fn renderFragments(self: *Builder, fragments: []const SourceFragment, native_host: ?*compiler.NativeArticleHost) !void {
        var rendered: std.ArrayList(compiler.Block) = .empty;
        defer rendered.deinit(self.a);
        for (fragments) |fragment| {
            const tracked = fragment.missing orelse MissingText.untracked(fragment.source);
            const previous_root = self.renderer.content_root;
            const previous_tables = self.renderer.root_wiki_table_range;
            const previous_text_scope = self.renderer.bounded_text_class_scope;
            const previous_native_classes = self.renderer.native_source_class_range;
            const previous_thumbnail_binding = self.renderer.selected_thumbnail_binding;
            const previous_text_source = self.renderer.bounded_text_class_source;
            if (fragmentContentRoot(fragment, tracked) == .parser_output) self.renderer.content_root = .parser_output;
            bindFragmentRootWikiTables(self.renderer, fragment, tracked);
            bindFragmentTextClassScope(self.renderer, fragment, tracked);
            defer self.renderer.content_root = previous_root;
            defer self.renderer.root_wiki_table_range = previous_tables;
            defer self.renderer.bounded_text_class_scope = previous_text_scope;
            defer self.renderer.native_source_class_range = previous_native_classes;
            defer self.renderer.selected_thumbnail_binding = previous_thumbnail_binding;
            defer self.renderer.bounded_text_class_source = previous_text_source;
            const native_scope = NativeArticleRenderScope.enter(native_host, tracked, fragment, false);
            defer native_scope.deinit();
            try rendered.appendSlice(self.a, try self.renderer.renderBodyWithFragmentPreAndMissing(tracked, fragment.pre));
        }
        try self.consume(try rendered.toOwnedSlice(self.a));
    }

    fn consume(self: *Builder, rendered: []const compiler.Block) !void {
        var section_start: usize = 0;
        for (rendered, 0..) |item, i| {
            if (item.kind == .heading) {
                try self.flush(rendered[section_start..i]);
                self.started = true;
                self.is_heading = true;
                self.heading_style = item.section_heading_style;
                self.expected_heading_pair = item.expected_heading_pair;
                self.heading_source_offset = item.heading_source_offset;
                self.heading_authored_id = item.heading_authored_id;
                self.title_spans = item.spans;
                self.title_depth = item.depth;
                self.title_list_path = item.list_path;
                self.title = trimHeading(try compiler.plainText(self.a, item.spans));
                self.level = item.level;
                section_start = i + 1;
            } else {
                self.started = true;
            }
        }
        try self.flush(rendered[section_start..]);
    }
};
fn workAlloc(a: A, title: []const u8, language: []const u8, source: []const u8, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: compiler.ReferenceDefinitions) !Work {
    return workAllocWithPoem(a, title, language, source, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, null);
}
fn workAllocWithPoem(a: A, title: []const u8, language: []const u8, source: []const u8, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: compiler.ReferenceDefinitions, poem_phase: ?*const PoemPhase) !Work {
    return workAllocWithPoemFragments(a, title, language, source, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, &.{});
}
fn workAllocWithPoemFragments(a: A, title: []const u8, language: []const u8, source: []const u8, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: compiler.ReferenceDefinitions, poem_phase: ?*const PoemPhase, fragments: []const SourceFragment) !Work {
    return workAllocWithMissingFragments(a, title, language, MissingText.untracked(source), link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, fragments, null, null, .unknown, false);
}
// Only a builder-issued range from the observed complete page can retain this
// root. Equal copied bytes, inherited wrappers and unknown fragments decline.
fn bindWholeTextClassScope(renderer: *compiler.Renderer, source: MissingText) void {
    renderer.native_source_class_range = null;
    renderer.local_link_binding = null;
    renderer.figure_class_source_binding = null;
    renderer.selected_thumbnail_binding = null;
    renderer.observed_image_map_source = null;
    renderer.source_element_binding = null;
    renderer.bounded_text_class_scope = null;
    renderer.bounded_text_class_source = null;
    if (renderer.content_root != .parser_output) return;
    const sizing = renderer.context.figure_sizing orelse return;
    const observed = sizing.text_class_scope orelse return;
    if (source.bytes.ptr != observed.source.ptr or source.bytes.len != observed.source.len) return;
    renderer.bounded_text_class_scope = observed.scope;
    renderer.bounded_text_class_source = source.bytes;
}

fn bindFragmentObservedImageMapSource(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.observed_image_map_source = null;
    if (fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const sizing = renderer.context.figure_sizing orelse return;
    if (sizing.resolve_image_map_no_link_fn == null) return;
    const range = fragment.parser_output_range.?;
    const original = range.original_page orelse return;
    // This is the existing Builder-issued unchanged-page relation, not a
    // string search. The callback still requires the selected original pointer.
    if (original.len != range.page.len or !std.mem.eql(u8, original, range.page) or
        range.start > original.len or tracked.bytes.len > original.len - range.start or
        !std.mem.eql(u8, tracked.bytes, original[range.start..][0..tracked.bytes.len])) return;
    renderer.observed_image_map_source = .{ .owner = tracked.bytes, .original = original[range.start..][0..tracked.bytes.len] };
}

fn bindFragmentNativeSourceClasses(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.native_source_class_range = null;
    if (fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const held = fragment.parser_output_range.?;
    const proof = held.native_source_class_proof orelse return;
    if (held.page.ptr != proof.source.bytes.ptr or held.page.len != proof.source.bytes.len) return;
    const range: compiler.NativeSourceClassRange = .{ .proof = proof, .start = held.start, .prepared = tracked };
    if (!compiler.nativeSourceClassRangeCurrent(range, tracked, renderer.context.table_styles)) return;
    renderer.native_source_class_range = range;
}

fn selectedFragmentOccurrence(fragment: SourceFragment, tracked: MissingText, source: []const u8) ?[]const u8 {
    if (fragmentContentRoot(fragment, tracked) != .parser_output or tracked.lost_missing_range or tracked.generated_source != null) return null;
    const range = fragment.parser_output_range.?;
    const original = range.original_page orelse return null;
    if (!std.mem.eql(u8, original, range.page)) return null;
    const begin = std.math.sub(usize, @intFromPtr(source.ptr), @intFromPtr(original.ptr)) catch return null;
    if (begin > original.len or source.len > original.len - begin or begin < range.start) return null;
    const offset = begin - range.start;
    if (offset > tracked.bytes.len or source.len > tracked.bytes.len - offset) return null;
    const piece = tracked.bytes[offset..][0..source.len];
    return if (std.mem.eql(u8, piece, source)) piece else null;
}

fn bindDefinitionLines(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.definition_lines = .{ null, null };
    const sizing = renderer.context.figure_sizing orelse return;
    const region = sizing.literal_region orelse return;
    if (region.definition_ids.len == 0 or region.definition_ids.len > renderer.definition_lines.len or
        tracked.generated_source != null or tracked.lost_missing_range or fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const range = fragment.parser_output_range.?;
    const original = range.definition_original orelse return;
    if (original.ptr != region.page.ptr or original.len != region.page.len) return;
    for (region.definition_ids, 0..) |proof, i| {
        const n = proof.line.len;
        if (proof.start > original.len or n > original.len - proof.start or
            !std.mem.eql(u8, original[proof.start..][0..n], proof.line)) continue;
        const start = mapped: {
            if (range.source_element_projection) |projection| {
                if (projection.original.bytes.ptr != original.ptr or projection.original.bytes.len != original.len or
                    projection.prepared.ptr != range.page.ptr or projection.prepared.len != range.page.len) continue;
                break :mapped projection.preparedRange(proof.start, n) orelse continue;
            }
            if (range.definition_run_start) |first| {
                if (region.definition_ids.len != 2 or proof.start < region.definition_ids[0].start) continue;
                break :mapped std.math.add(usize, first, proof.start - region.definition_ids[0].start) catch continue;
            }
            continue;
        };
        if (start < range.start or start - range.start > tracked.bytes.len or n > tracked.bytes.len - (start - range.start)) continue;
        const line = tracked.bytes[start - range.start ..][0..n];
        if (std.mem.eql(u8, line, proof.line)) renderer.definition_lines[i] = .{ .line = line, .id = proof.id, .label = proof.label };
    }
}

fn bindNavHeads(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.nav_heads = .{ null, null };
    const sizing = renderer.context.figure_sizing orelse return;
    const region = sizing.literal_region orelse return;
    if (region.nav_heads.len != 2 or tracked.generated_source != null or tracked.lost_missing_range or
        fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const range = fragment.parser_output_range orelse return;
    const original = range.definition_original orelse return;
    if (original.ptr != region.page.ptr or original.len != region.page.len) return;
    for (region.nav_heads, 0..) |proof, i| {
        const n = proof.frame.len;
        if (proof.start > original.len or n > original.len - proof.start or
            !std.mem.eql(u8, original[proof.start..][0..n], proof.frame)) continue;
        const from_projection = if (range.source_element_projection) |projection| projected: {
            if (projection.original.bytes.ptr != original.ptr or projection.original.bytes.len != original.len or
                projection.prepared.ptr != range.page.ptr or projection.prepared.len != range.page.len) break :projected null;
            break :projected projection.preparedRange(proof.start, n);
        } else null;
        const start = from_projection orelse projected: {
            const first = range.nav_head_run_start orelse continue;
            const delta = std.math.sub(usize, proof.start, region.nav_heads[0].start) catch continue;
            break :projected std.math.add(usize, first, delta) catch continue;
        };
        if (start < range.start or start - range.start > tracked.bytes.len or n > tracked.bytes.len - (start - range.start)) continue;
        const frame = tracked.bytes[start - range.start ..][0..n];
        if (std.mem.eql(u8, frame, proof.frame)) renderer.nav_heads[i] = .{ .frame = frame, .id = proof.id, .label = proof.label };
    }
}

fn bindFragmentTextClassScope(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    bindNavHeads(renderer, fragment, tracked);
    bindDefinitionLines(renderer, fragment, tracked);
    renderer.selected_timed_audio = null;
    if (fragmentContentRoot(fragment, tracked) == .parser_output and !tracked.lost_missing_range and tracked.generated_source == null) {
        if (fragment.parser_output_range.?.timed_audio) |selected| {
            if (selected.offsetIn(fragment.source)) |offset| {
                const token = tracked.bytes[offset..][0..selected.source.len];
                if (std.mem.eql(u8, token, selected.source)) {
                    var bound = selected;
                    bound.source = token;
                    renderer.selected_timed_audio = bound;
                }
            }
        }
    }
    renderer.wrapped_heading_source = null;
    renderer.selected_inline_fragment = null;
    renderer.selected_phonos_source = null;
    if (renderer.context.table_styles) |styles| {
        if (styles.selected_wrapped_heading) |selected| renderer.wrapped_heading_source = selectedFragmentOccurrence(fragment, tracked, selected.source);
        if ((styles.selected_phonos.len != 0 or styles.selected_descriptions.len != 0 or styles.selected_terms.len != 0) and fragmentContentRoot(fragment, tracked) == .parser_output and !tracked.lost_missing_range and tracked.generated_source == null) {
            const range = fragment.parser_output_range.?;
            // Only an issued insertion projection is required here. The
            // original_page capability stays withheld for transformed pages.
            // The consumer still matches the exact selected original token.
            if (styles.selected_phonos.len != 0) if (range.source_element_projection) |projection| {
                if (projection.prepared.ptr == range.page.ptr and projection.prepared.len == range.page.len and
                    std.mem.eql(u8, tracked.bytes, fragment.source))
                    renderer.selected_phonos_source = .{ .projection = projection, .owner = tracked,
                        .page_start = range.start, .selected = styles.selected_phonos };
            };
            if (range.original_page) |original| {
                if (std.mem.eql(u8, original, range.page) and range.start <= original.len and tracked.bytes.len <= original.len - range.start) {
                    const input = original[range.start..][0..tracked.bytes.len];
                    if (std.mem.eql(u8, input, tracked.bytes)) renderer.selected_inline_fragment = .{ .original = input, .projected = tracked.bytes };
                }
            }
        }
    }
    bindFragmentNativeSourceClasses(renderer, fragment, tracked);
    bindFragmentObservedImageMapSource(renderer, fragment, tracked);
    bindFragmentSourceElements(renderer, fragment, tracked);
    bindFragmentFigureClassSource(renderer);
    renderer.bounded_text_class_scope = null;
    renderer.bounded_text_class_source = null;
    if (fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const original = fragment.parser_output_range.?.original_page orelse return;
    const sizing = renderer.context.figure_sizing orelse return;
    const observed = sizing.text_class_scope orelse return;
    if (original.ptr != observed.source.ptr or original.len != observed.source.len) return;
    renderer.bounded_text_class_scope = observed.scope;
    renderer.bounded_text_class_source = tracked.bytes;
}

// A transformed page may have no whole-page class-preserving transition.
// Retain only the independently selected context here; the Figure consumer must
// still map its complete File and caption through this operation's exact copies.
fn bindFragmentFigureClassSource(renderer: *compiler.Renderer) void {
    renderer.figure_class_source_binding = null;
    const binding = renderer.source_element_binding orelse return;
    const sizing = renderer.context.figure_sizing orelse return;
    const observed = sizing.text_class_scope orelse return;
    if (binding.scope != observed.scope or observed.scope.complete_ancestor_class_superset == null or
        binding.projection.original.bytes.ptr != observed.source.ptr or
        binding.projection.original.bytes.len != observed.source.len) return;
    renderer.figure_class_source_binding = binding;
}

fn bindFragmentSourceElements(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.local_link_binding = null;
    renderer.source_element_binding = null;
    renderer.selected_thumbnail_binding = null;
    renderer.table_direction_binding = null;
    renderer.container_disclosure_binding = null;
    if (fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const range = fragment.parser_output_range.?;
    const projection = range.source_element_projection orelse return;
    if (projection.prepared.ptr == range.page.ptr and projection.prepared.len == range.page.len)
        bindContainerDisclosureProjection(renderer, projection, tracked, range.start);
    if (renderer.context.local_link_targets) |selected| {
        if (projection.prepared.ptr == range.page.ptr and projection.prepared.len == range.page.len and
            projection.original.bytes.ptr == selected.source.ptr and projection.original.bytes.len == selected.source.len and
            !tracked.unknown and !tracked.lost_missing_range and tracked.generated_source == null and
            std.mem.eql(u8, tracked.bytes, fragment.source))
            renderer.local_link_binding = .{ .projection = projection, .owner = tracked, .page_start = range.start };
    }
    const sizing = renderer.context.figure_sizing orelse return;
    if (sizing.selected_default_thumbnails) |selected| {
        const original = projection.original;
        if (projection.prepared.ptr == range.page.ptr and projection.prepared.len == range.page.len and
            original.bytes.ptr == selected.source.ptr and original.bytes.len == selected.source.len and
            !original.unknown and !original.lost_missing_range and original.generated_source == null and
            !tracked.unknown and !tracked.lost_missing_range and tracked.generated_source == null and
            std.mem.eql(u8, tracked.bytes, fragment.source))
            renderer.selected_thumbnail_binding = .{ .projection = projection, .owner = tracked, .page_start = range.start };
    }
    for ([_]?compiler.TableContainingDirectionSource{ sizing.table_containing_direction, sizing.table_float_source }) |optional| if (optional) |direction| {
        const binding: compiler.TableDirectionRangeBinding = .{ .projection = projection, .owner = tracked, .page_start = range.start };
        if (projection.prepared.ptr == range.page.ptr and projection.prepared.len == range.page.len and
            projection.original.bytes.ptr == direction.source.ptr and projection.original.bytes.len == direction.source.len and
            binding.sourceCurrent(direction, renderer.context.table_styles) and
            std.mem.eql(u8, tracked.bytes, fragment.source))
            renderer.table_direction_binding = binding;
    };
    const observed = sizing.text_class_scope orelse return;
    const sibling = if (observed.scope.source_siblings_source) |issued|
        observed.scope.source_siblings.len != 0 and issued.ptr == observed.source.ptr and issued.len == observed.source.len else false;
    const root_tables = if (observed.scope.source_root_tables_source) |issued|
        observed.scope.source_root_tables.len != 0 and issued.ptr == observed.source.ptr and issued.len == observed.source.len else false;
    const page_styles = observed.scope.page_style_root != null and observed.scope.page_styles != null and
        observed.scope.page_styles == renderer.context.table_styles;
    if ((!sibling and !root_tables and !page_styles) or projection.prepared.ptr != range.page.ptr or projection.prepared.len != range.page.len or
        projection.original.bytes.ptr != observed.source.ptr or projection.original.bytes.len != observed.source.len or
        !std.mem.eql(u8, tracked.bytes, fragment.source)) return;
    renderer.source_element_binding = .{ .scope = observed.scope, .projection = projection, .owner = tracked, .page_start = range.start };
}

fn bindFragmentRootWikiTables(renderer: *compiler.Renderer, fragment: SourceFragment, tracked: MissingText) void {
    renderer.root_wiki_table_range = null;
    if (fragmentContentRoot(fragment, tracked) != .parser_output) return;
    const proof = fragment.parser_output_range.?;
    if (proof.root_wiki_table_openings.len == 0 and proof.top_level_wiki_table_openings.len == 0) return;
    renderer.root_wiki_table_range = .{ .page = proof.page, .start = proof.start, .prepared = proof.prepared, .openings = proof.root_wiki_table_openings, .top_level_openings = proof.top_level_wiki_table_openings };
}

fn fragmentContentRoot(fragment: SourceFragment, tracked: MissingText) compiler.ContentRoot {
    const proof = fragment.parser_output_range orelse return .unknown;
    if (fragment.original_start != proof.start or proof.start > proof.page.len or
        fragment.source.len > proof.page.len - proof.start or
        fragment.source.ptr != proof.page[proof.start..].ptr or
        tracked.bytes.ptr != proof.prepared.ptr or tracked.bytes.len != proof.prepared.len or
        tracked.bytes.len != fragment.source.len or
        fragment.pre.initial.len != 0 or fragment.pre.trailing.len != 0 or fragment.pre.initial_block_pre) return .unknown;
    return .parser_output;
}

fn completeContentFragments(source: MissingText, fragments: []const SourceFragment, requested: compiler.ContentRoot) compiler.ContentRoot {
    if (requested != .parser_output or fragments.len == 0) return requested;
    if (fragments.len != 1) return .unknown;
    const fragment = fragments[0];
    if (fragment.original_start != 0 or !std.mem.eql(u8, fragment.source, source.bytes) or
        fragment.pre.initial.len != 0 or fragment.pre.trailing.len != 0 or fragment.pre.initial_block_pre) return .unknown;
    return .parser_output;
}

const NativeArticleRenderScope = struct {
    host: ?*compiler.NativeArticleHost = null,
    previous_source: ?MissingText = null,
    previous_snapshot: ?[32]u8 = null,
    previous_fragment: ?compiler.NativeArticleFragment = null,
    previous_whole_page: bool = false,

    fn enter(host: ?*compiler.NativeArticleHost, tracked: MissingText, fragment: ?SourceFragment, whole_page: bool) @This() {
        const value = host orelse return .{};
        const scope: @This() = .{ .host = value, .previous_source = value.active_source, .previous_snapshot = value.active_snapshot,
            .previous_fragment = value.active_fragment, .previous_whole_page = value.active_whole_page };
        value.active_source = tracked;
        value.active_snapshot = compiler.NativeArticleHost.snapshot(tracked);
        value.active_fragment = null;
        value.active_whole_page = whole_page and fragment == null and compiler.NativeArticleHost.sameSource(value.source, tracked);
        if (fragment) |part| if (fragmentContentRoot(part, tracked) == .parser_output) {
            const proof = part.parser_output_range.?;
            const starts_page = proof.start == 0 and std.mem.eql(u8, tracked.bytes, part.source) and
                (if (proof.original_page) |original| std.mem.eql(u8, original, proof.page) else true);
            value.active_fragment = .{ .page = proof.page, .original_page = proof.original_page, .literal_prefix = proof.literal_prefix,
                .start = proof.start, .prepared = proof.prepared, .starts_page = starts_page,
                .static_paragraph_openings = proof.static_paragraph_openings, .static_paragraph_original_prefix = proof.static_paragraph_original_prefix,
                .static_example_openings = proof.static_example_openings, .static_example_original_prefix = proof.static_example_original_prefix,
                .observed_box_table_heading_root = proof.observed_box_table_heading_root };
        };
        return scope;
    }

    fn deinit(self: @This()) void {
        const host = self.host orelse return;
        host.active_source = self.previous_source;
        host.active_snapshot = self.previous_snapshot;
        host.active_fragment = self.previous_fragment;
        host.active_whole_page = self.previous_whole_page;
    }
};

fn nativeArticleHostForFinalBody(renderer: *compiler.Renderer, source: MissingText,
    title: []const u8, language_code: ?[]const u8, final_owner: bool) ?compiler.NativeArticleHost
{
    if (!final_owner) return null;
    // This final worker constructs semantic Entry content. The native reader's
    // title/navigation chrome is outside that source-CSS tree; source IDs and
    // headings remain on the ordered Entry body itself. Observers receive none.
    return .{ .renderer = renderer, .source = source, .title = title, .language_code = language_code orelse "",
        .external_id_subjects_absent = true, .external_heading_subjects_absent = true,
        .native_paragraph_css_subjects = true };
}

const CompleteActionFocus = struct {
    renderer: *compiler.Renderer,
    fn spans(self: *@This(), values: []const compiler.Span) anyerror!void {
        for (values) |span| try self.renderer.consumeCompletedActionFocus(span);
    }
    fn block(self: *@This(), value: *compiler.Block) anyerror!void { self.renderer.consumeCompletedInlineOwner(value); }
};

fn completeActionFocus(renderer: *compiler.Renderer, work: Work) !void {
    if (renderer.required_page_source_focus == null) return;
    var context: CompleteActionFocus = .{ .renderer = renderer };
    var walk: CompilerWalk = .{};
    for (work.sections) |section| {
        try walk.spans(&context, section.title_spans);
        try walk.blocks(&context, section.blocks, 0);
    }
    try walk.references(&context, work.references);
    for (work.media_caption_spans) |caption| try walk.spans(&context, caption);
    renderer.finishCompletedActionFocus();
}

const CompleteSelectedTimedAudio = struct {
    fn block(_: *@This(), _: *compiler.Block) error{}!void {}
    fn spans(_: *@This(), values: []const compiler.Span) anyerror!void {
        for (values) |span| if (span.selected_timed_audio_completion) |completed| {
            if (completed.*) return error.TimedAudioObservationDuplicated;
            completed.* = true;
        };
    }
};

fn completeSelectedTimedAudio(work: Work, fragments: []const SourceFragment) !void {
    for (fragments) |fragment| {
        const range = fragment.parser_output_range orelse continue;
        if (range.timed_audio == null) continue;
        var context: CompleteSelectedTimedAudio = .{};
        var walk: CompilerWalk = .{};
        for (work.sections) |section| try walk.blocks(&context, section.blocks, 0);
        return;
    }
}

fn workAllocWithMissingFragments(a: A, title: []const u8, language: []const u8, tracked: MissingText, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: compiler.ReferenceDefinitions, poem_phase: ?*const PoemPhase, fragments: []const SourceFragment, table_styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, content_root: compiler.ContentRoot, final_document_body: bool) !Work {
    return workAllocWithMissingFragmentsIn(a, title, language, tracked, link_trail, namespace_catalog, behavior_switches, image_options, reference_context, poem_phase, fragments, table_styles, figure_sizing, content_root, final_document_body, null, null, false);
}

fn workAllocWithMissingFragmentsIn(a: A, title: []const u8, language: []const u8, tracked: MissingText, link_trail: ir.LinkTrail, namespace_catalog: ?*const NamespaceRegistry, behavior_switches: ?*const BehaviorRegistry, image_options: ?*const ImageRegistry, reference_context: compiler.ReferenceDefinitions, poem_phase: ?*const PoemPhase, fragments: []const SourceFragment, table_styles: ?*const TableStyleProfile, figure_sizing: ?FigureSizingSource, content_root: compiler.ContentRoot, final_document_body: bool, native_body_language: ?[]const u8, source_classified_language: ?[]const u8, native_article_owner: bool) !Work {
    const whole_body = for (fragments) |fragment| {
        if (fragment.whole_body) break true;
    } else false;
    var renderer: compiler.Renderer = .{
        .a = a,
        .page_source_focus_completion = true,
        .native_body_language = native_body_language, .source_classified_language = source_classified_language,
        .literal_url_root = tracked.bytes,
        .content_root = if (whole_body) content_root else completeContentFragments(tracked, fragments, content_root),
        .context = .{
            .title = title,
            .unclosed_fragment_trace = try unclosedFragmentTraceFromEnv(),
            .table_viewport_trace = try tableViewportTraceFromEnv(),
            .language = if (language.len == 0) "English" else language,
            .link_trail = link_trail,
            .namespace_catalog = namespace_catalog,
            .behavior_switches = behavior_switches,
            .image_options = image_options, .table_styles = table_styles, .figure_sizing = figure_sizing,
            .poem_phase = poem_phase,
            .citations = reference_context.citations,
            .content_conversion = reference_context.content_conversion,
            .display_title_precedence = reference_context.display_title_precedence,
            .normal_title_defaults = reference_context.normal_title_defaults,
            .container_disclosures = reference_context.container_disclosures,
            .local_link_targets = reference_context.local_link_targets,
            .body_link_continuations = reference_context.body_link_continuations,
            .external_links_prepared = reference_context.citations != null,
        },
    };
    // One final Entry owner, not one receipt per selected source fragment.
    renderer.budgetForSource(tracked.bytes.len);
    bindContainerDisclosureProjection(&renderer, reference_context.container_disclosure_projection, tracked, 0);
    bindSelectedPhonosProjection(&renderer, tracked, renderer.context.table_styles, reference_context.container_disclosure_projection);
    var native_host = nativeArticleHostForFinalBody(&renderer, tracked, title, native_body_language,
        native_article_owner and final_document_body);
    renderer.native_article_host = if (native_host) |*host| host else null;
    renderer.page_reference_definitions = reference_context.items;
    renderer.fallbacks.merge(reference_context.fallbacks);
    renderer.context.content_conversion = try compiler.pageContentConversion(a, tracked.bytes, renderer.context);
    var builder: Builder = .{
        .a = a,
        .renderer = &renderer,
        .title = if (language.len == 0) title else language,
    };
    if (final_document_body) renderer.traceDocumentBody(.begin, tracked, fragments.len, null);
    var body_finished = false;
    errdefer if (!body_finished) renderer.traceDocumentBody(.failure, tracked, fragments.len, null);
    if (fragments.len == 0 or whole_body) {
        bindWholeTextClassScope(&renderer, tracked);
        // Invalid custody keeps the original whole-body rendering and its
        // refusal behavior; it never turns an arbitrary slice into ancestry.
        if (fragments.len == 1 and whole_body and content_root == .parser_output) {
            const fragment = fragments[0];
            if (fragment.original_start == 0 and fragment.source.ptr == tracked.bytes.ptr and fragment.source.len == tracked.bytes.len and
                std.meta.eql(fragment.missing orelse MissingText.untracked(fragment.source), tracked) and
                fragmentContentRoot(fragment, tracked) == .parser_output)
            {
                bindFragmentRootWikiTables(&renderer, fragment, tracked);
                bindFragmentTextClassScope(&renderer, fragment, tracked);
            }
        }
        const native_scope = NativeArticleRenderScope.enter(if (native_host) |*host_value| host_value else null,
            tracked, if (fragments.len == 1) fragments[0] else null, fragments.len == 0 and content_root == .parser_output);
        defer native_scope.deinit();
        try builder.renderWithMissing(tracked);
