    const decoded = try codec.decodeAlloc(a, bytes, "ଜଘନ କୂପ", .language, .{ .code = "", .heading = "Unclassified" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    var visible: std.ArrayList(u8) = .empty;
    var links: usize = 0;
