            try visible.appendSlice(a, span.text);
            if (span.kind == .link) {
                try std.testing.expectEqualStrings("ବିଶେଷ୍ୟ", span.target);
                try std.testing.expectEqualStrings("ବିଶେଷ୍ୟ", span.text);
                links += 1;
