        const synonym_targets = [_][]const u8{ "parpayuela", "llinguaxe", "llinguax", "idioma" };
        var synonyms: usize = 0;
        for (stored.entry.sections[2].blocks) |block| for (block.spans) |span| if (span.kind == .link) {
