    const actual = try compileReportedWithLinkTrailAlloc(a, "niçard", .language, "Occitan", "oc", source, null, .{}, &namespaces, &actual_report);
    const expected = try compileReportedWithLinkTrailAlloc(a, "niçard", .language, "Occitan", "oc", reference_source, null, .{}, &namespaces, &expected_report);
    try std.testing.expectEqualSlices(u8, expected, actual);
    try std.testing.expectEqualDeep(expected_report, actual_report);
    const stored = try codec.decodeAlloc(a, actual, "niçard", .language, .{ .code = "oc", .heading = "Occitan" });
    try std.testing.expectEqualStrings("DPRM", actual[0..4]);
    var tooltip_witnesses: u8 = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| if (span.tooltip) |tip| {
        if (std.mem.eql(u8, tip, "Entre-senhas fonologicas sul mot : niçard")) tooltip_witnesses |= 1;
        if (std.mem.eql(u8, tip, "AFI") and std.mem.eql(u8, span.text, "niˈsart")) tooltip_witnesses |= 2;
        if (tip.len == 0 and std.mem.indexOf(u8, span.text, "Traduccions") != null) tooltip_witnesses |= 4;
    };
    try std.testing.expectEqual(@as(u8, 7), tooltip_witnesses);
    var sized_headings: u8 = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        if (block.kind != .heading) continue;
        for (block.spans) |span| {
            const language_title = std.mem.eql(u8, span.text, "Occitan");
            const adjective_title = std.mem.indexOf(u8, span.text, "Adjectiu") != null;
            const noun_title = std.mem.indexOf(u8, span.text, "Nom comun") != null;
            if (!language_title and !adjective_title and !noun_title) continue;
            try std.testing.expectEqual(blobs.presentation_types.FontScaleBasis.normal_body, span.font_scale_basis);
            try std.testing.expectEqual(@as(?f32, if (language_title) 1.3 else 1.2), span.font_scale);
            if (language_title) {
                try std.testing.expect(span.kind == .link);
                try std.testing.expectEqualStrings("occitan", span.target);
            }
            sized_headings |= if (language_title) @as(u8, 1) else if (adjective_title) 2 else 4;
        }
    };
    try std.testing.expectEqual(@as(u8, 7), sized_headings);
    try std.testing.expectEqualSlices(u8, actual, try codec.encodeAlloc(a, stored));
    try std.testing.expectEqual(@as(usize, 1), stored.entry.references.len);
    var reference_text: std.ArrayList(u8) = .empty;
    var nissart_actions: usize = 0;
    for (stored.entry.references[0].spans) |span| {
        try reference_text.appendSlice(a, span.text);
        if (span.kind == .link and std.mem.eql(u8, span.target, "nissart")) {
            nissart_actions += 1;
            try std.testing.expectEqualStrings("nissart", span.text);
            try std.testing.expect(span.italic);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), nissart_actions);
    try std.testing.expectEqualStrings("En nòrma classica, s'escriu niçard niçarda. En nòrma mistralenca, s'escriu <niçart niçarda> o mens correctament <nissart nissarda>.", reference_text.items);
    var definitions: usize = 0;
    var tables: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        if (block.kind == .definition) definitions += 1;
        if (block.table) |table| {
            tables += 1;
            // The null-profile resolver retains independent authored paint,
            // solid border and margin. Width remains the separate HTML hint.
            try std.testing.expectEqualDeep(types.TableStyle{ .background = "#fafafa",
                .border = .{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = "#aaaaaa" } }, .margins = .{
                .top = .{ .unit = .em, .value = 1 },
                .right = .{ .unit = .px, .value = 0 },
                .bottom = .{ .unit = .em, .value = 1 },
                .left = .{ .unit = .px, .value = 0 },
            } }, table.style.?);
            try std.testing.expectEqualDeep(types.TableGeometry{ .width = .{ .unit = .percent, .value = 100 } }, table.geometry.?);
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            // Cell padding and dotted border are not projected without a CSS profile.
            try std.testing.expectEqualDeep(types.CellStyle{
                .width = .{ .unit = .percent, .value = 50 }, .vertical_align = .top,
            }, table.rows[0].cells[0].style.?);
            try std.testing.expectEqualStrings("#ffffff", table.rows[0].cells[0].background.?);
        }
    };
    try std.testing.expectEqual(@as(usize, 2), definitions);
    try std.testing.expectEqual(@as(usize, 1), tables);
    // Only the newly represented cell hints require M. Removing those exact
    // authored attributes and only those fields recovers the complete H graph.
    const cell_hints = "valign=\"top\" width=\"50%\"";
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, source, cell_hints));
    const legacy_source = try std.mem.replaceOwned(u8, a, source, cell_hints, "");
    var legacy_report: Fallbacks = .{};
    const legacy_bytes = try compileReportedWithLinkTrailAlloc(a, "niçard", .language, "Occitan", "oc", legacy_source, null, .{}, &namespaces, &legacy_report);
    try std.testing.expectEqualStrings("DPRH", legacy_bytes[0..4]);
    try std.testing.expectEqualDeep(actual_report, legacy_report);
    const legacy = try codec.decodeAlloc(a, legacy_bytes, "niçard", .language, .{ .code = "oc", .heading = "Occitan" });
    const normalized = try codec.decodeAlloc(a, actual, "niçard", .language, .{ .code = "oc", .heading = "Occitan" });
    var normalized_cells: usize = 0;
    for (normalized.entry.sections) |section| for (@constCast(section.blocks)) |*block| if (block.table) |*table| {
        try std.testing.expectEqual(@as(usize, 1), table.rows.len);
        try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
        @constCast(table.rows[0].cells)[0].style = null;
        normalized_cells += 1;
    };
    try std.testing.expectEqual(@as(usize, 1), normalized_cells);
    try std.testing.expectEqualDeep(legacy, normalized);
    try std.testing.expectEqualSlices(u8, legacy_bytes, try codec.encodeAlloc(a, normalized));
    // The repeated heading icon contributes one deduplicated catalog asset.
    // Its unsupported middle option does not establish a typed inline occurrence.
    try std.testing.expectEqual(@as(usize, 2), stored.entry.media.len);
    var audio_assets: usize = 0;
    var heading_assets: usize = 0;
    for (stored.entry.media) |asset| {
        if (std.mem.eql(u8, asset.file, "LL-Q14185 (oci)-Davidgrosclaude-niçard.wav")) {
            try std.testing.expectEqual(types.MediaKind.audio, asset.kind);
            try std.testing.expectEqualStrings("LL-Q14185 (oci)-Davidgrosclaude-niçard.wav", asset.caption);
            audio_assets += 1;
        } else if (std.mem.eql(u8, asset.file, "Open book 01.svg")) {
            try std.testing.expectEqual(types.MediaKind.image, asset.kind);
            try std.testing.expectEqualStrings("Open book 01.svg", asset.caption);
            heading_assets += 1;
        } else return error.TestUnexpectedResult;
    }
    try std.testing.expectEqual(@as(usize, 1), audio_assets);
    try std.testing.expectEqual(@as(usize, 1), heading_assets);
    const raw = [_]compiler.Span{.{ .text = "<nissart nissarda>" }};
    const split = [_]compiler.Span{
        .{ .text = "<" },
        .{ .kind = .link, .text = "nissart", .target = "nissart" },
        .{ .text = " nissarda>" },
    };
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &raw, null));
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &split, null));
    const unresolved = [_]compiler.Span{.{ .kind = .link, .text = "label", .target = "{{missing}}", .provenance = .protected_literal }};
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, &unresolved, null));
}

