    }
    try std.testing.expectEqual(@as(usize, 10), styled_cell_count);
    try std.testing.expectEqual(@as(usize, 5), styled_header_count);
    // Both real-input paths use the same authenticated full profile.
    // The infobox table vertical-align:sub remains outside the typed subset.
    const inflection_at = inflection_position.?;
    const baseline_section = stored.entry.sections[inflection_at.section];
    const styled_section = styled.entry.sections[inflection_at.section];
    try std.testing.expectEqual(baseline_section.blocks.len, styled_section.blocks.len);
    const baseline_inflection = baseline_section.blocks[inflection_at.block].table.?;
    const styled_inflection = styled_section.blocks[inflection_at.block].table.?;
    try std.testing.expectEqualDeep(expected_inflection_style, baseline_inflection.style.?);
    try std.testing.expectEqualDeep(expected_inflection_style, styled_inflection.style.?);

    try std.testing.expectEqualDeep(stored, styled);
    try actual_sizing.checkFigures(a, stored.entry);
    // Preserve the historical style-normalization oracle on independent codec-
    // owned copies of both full-profile graphs, never on the real baseline.
    const normalized_baseline = try codec.decodeAlloc(a, encoded, "skakavica", .language, .{ .code = "", .heading = "Unclassified" });
    const normalized_styled = try codec.decodeAlloc(a, styled_bytes, "skakavica", .language, .{ .code = "", .heading = "Unclassified" });
    for ([_]types.Stored{ normalized_baseline, normalized_styled }) |normalized| {
        const mutable_blocks = @constCast(normalized.entry.sections[inflection_at.section].blocks);
        mutable_blocks[inflection_at.block].table.?.style = expected_baseline_inflection_style;
        const mutable_reference_blocks = @constCast(normalized.entry.references[0].blocks.?);
        const normalized_table = &mutable_reference_blocks[1].table.?;
        normalized_table.style = null;
        for (normalized_table.rows) |row| for (@constCast(row.cells)) |*cell| {
            cell.style = null;
            cell.background = null;
        };
    }
    try std.testing.expectEqualDeep(normalized_baseline, normalized_styled);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, normalized_baseline), try codec.encodeAlloc(a, normalized_styled));

    // Preserve both historical version boundaries after removing only the four
    // explicit cell widths and two top hints from independent source/graphs.
    var legacy_source: []const u8 = source;
    for ([_][]const u8{ "width=\"65\"", "valign=\"top\" width=\"48%\"", "width=1%", "valign=top width=48%" }) |hint| {
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, legacy_source, hint));
        legacy_source = try std.mem.replaceOwned(u8, a, legacy_source, hint, "");
    }
    const legacy_bytes = try compileClassifiedWithHeadingAnchorsAndSourceMediaRootAlloc(a, "skakavica", .language, "Unclassified", "", MissingText.untracked(legacy_source), null, .{}, &namespaces, null, &images, .{}, null, null, &.{}, null, &.{}, null, &stylesheet_profile, figure_sizing, .parser_output);
    try std.testing.expectEqualStrings("DPRL", legacy_bytes[0..4]);
    const legacy = try codec.decodeAlloc(a, legacy_bytes, "skakavica", .language, .{ .code = "", .heading = "Unclassified" });
    const normalized_hints = try codec.decodeAlloc(a, encoded, "skakavica", .language, .{ .code = "", .heading = "Unclassified" });
    var widths: usize = 0;
    var tops: usize = 0;
    for (normalized_hints.entry.sections) |section| for (@constCast(section.blocks)) |*block| if (block.table) |*grid| {
        for (grid.rows) |row| for (@constCast(row.cells)) |*cell| if (cell.style) |value| {
            var remaining = value;
            if (remaining.width != null) widths += 1;
            if (remaining.vertical_align != null) tops += 1;
            remaining.width = null;
            remaining.vertical_align = null;
            cell.style = if (types.validCellStyle(remaining)) remaining else null;
        };
    };
    try std.testing.expectEqual(@as(usize, 4), widths);
    try std.testing.expectEqual(@as(usize, 2), tops);
    try std.testing.expectEqualDeep(legacy, normalized_hints);
    try std.testing.expectEqualSlices(u8, legacy_bytes, try codec.encodeAlloc(a, normalized_hints));
    const legacy_no_clear_source = try std.mem.replaceOwned(u8, a, legacy_source, clearer, "");
    const legacy_no_clear_bytes = try compileClassifiedWithHeadingAnchorsAndSourceMediaRootAlloc(a, "skakavica", .language, "Unclassified", "", MissingText.untracked(legacy_no_clear_source), null, .{}, &namespaces, null, &images, .{}, null, null, &.{}, null, &.{}, null, &stylesheet_profile, figure_sizing, .parser_output);
    try std.testing.expectEqualStrings("DPRJ", legacy_no_clear_bytes[0..4]);
    const legacy_no_clear = try codec.decodeAlloc(a, legacy_no_clear_bytes, "skakavica", .language, .{ .code = "", .heading = "Unclassified" });
    @constCast(normalized_hints.entry.sections)[1].blocks = normalized_hints.entry.sections[1].blocks[0..1];
    try std.testing.expectEqualDeep(legacy_no_clear, normalized_hints);
    try std.testing.expectEqualSlices(u8, legacy_no_clear_bytes, try codec.encodeAlloc(a, normalized_hints));

    // The actual published Reader establishes hrvatski/hr independently. Give
    // that owner to the same complete captured source/profile; organization
    // must be the only body change from the already checked unresolved record.
    const owned_bytes = try compileClassifiedWithHeadingAnchorsAndSourceMediaRootAlloc(
        a, "skakavica", .language, "hrvatski", "hr", MissingText.untracked(source),
        null, .{}, &namespaces, null, &images, .{}, null, null, &.{}, null, &.{},
        .{ .code = "hr", .heading = "hrvatski" }, &stylesheet_profile, figure_sizing, .parser_output,
    );
    const owned = try codec.decodeAlloc(a, owned_bytes, "skakavica", .language, .{ .code = "hr", .heading = "hrvatski" });
    try std.testing.expectEqualSlices(u8, owned_bytes, try codec.encodeAlloc(a, owned));
    try std.testing.expectEqualStrings("hrvatski", owned.entry.language.?);
    try std.testing.expectEqualStrings("hr", owned.entry.language_code);
    try std.testing.expectEqual(@as(usize, 1), owned.entry.organization.lexemes.len);
    const noun = owned.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("hrvatski", noun.language);
    try std.testing.expectEqualStrings("Noun", noun.kind);
    try std.testing.expectEqual(@as(usize, 0), noun.section);
    try std.testing.expectEqual(@as(usize, 1), noun.definitions.len);
    try std.testing.expectEqual(@as(usize, 3), noun.definitions[0].block);
    try std.testing.expect(noun.definitions[0].parent == null and noun.definitions[0].form == null and noun.etymology == null);
    try std.testing.expectEqual(@as(usize, 0), noun.definitions[0].examples.len + noun.definitions[0].quotations.len + noun.definitions[0].notes.len);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1, 2 }, noun.introduction);
    try std.testing.expectEqualSlices(usize, &.{ 4, 5, 6, 7, 8 }, noun.other_blocks);
    try std.testing.expectEqualSlices(usize, &.{ 1, 2, 3 }, noun.related_sections);
    try std.testing.expectEqual(@as(usize, 0), owned.entry.organization.other_sections.len);
    var owned_body = owned;
    owned_body.entry.language = styled.entry.language;
    owned_body.entry.language_code = styled.entry.language_code;
    owned_body.entry.organization = styled.entry.organization;
    try std.testing.expectEqualDeep(styled, owned_body);

}

test "reference block validation stays recursive and headings share the page registry" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "==English==\n===Repeated===\nbody<ref>===Repeated===\n{|\n| cell\n|}</ref><references/>";
    const unobserved_bytes = try compileAlloc(a, "entry", .language, "English", "en", source, null);
    const unobserved = try codec.decodeAlloc(a, unobserved_bytes, "entry", .language, .{ .code = "en", .heading = "English" });
    var unobserved_anchor = false;
    for (unobserved.entry.references[0].blocks.?) |block| if (block.kind == .heading) {
        try std.testing.expectEqualStrings("Repeated_2", block.anchor);
        unobserved_anchor = true;
    };
    try std.testing.expect(unobserved_anchor);
    const observed = try observeHeadingAnchorsAlloc(a, "entry", MissingText.untracked(source), .{}, null, null, null, .{}, null);
    const encoded = try compileReportedWithReferencesAndPhasesFragmentsAndHeadingAnchorsAlloc(a, "entry", .language, "English", "en", MissingText.untracked(source), null, .{}, null, null, null, .{}, null, null, &.{}, &observed, &.{.{ .owner_start = 0, .page_start = 0, .len = source.len }});
    const stored = try codec.decodeAlloc(a, encoded, "entry", .language, .{ .code = "en", .heading = "English" });
    const reference_blocks = stored.entry.references[0].blocks.?;
    var reference_anchor: []const u8 = "";
    for (reference_blocks) |block| if (block.kind == .heading) {
        reference_anchor = block.anchor;
    };
    try std.testing.expectEqualStrings("Repeated_2", reference_anchor);
    for (stored.entry.sections) |section| {
        try std.testing.expect(!std.mem.eql(u8, section.anchor, reference_anchor));
        for (section.blocks) |block| if (block.kind == .heading)
            try std.testing.expect(!std.mem.eql(u8, block.anchor, reference_anchor));
    }
    const raw = [_]compiler.Span{.{ .text = "{| raw |}" }};
    const blocks = [_]compiler.Block{.{ .kind = .paragraph, .spans = &raw }};
    const references = [_]compiler.Reference{.{ .number = 1, .group_number = 1, .blocks = &blocks }};
    var validation: ValidateCompilerSpans = .{ .a = a, .fallbacks = null };
    var walk: CompilerWalk = .{};
    try std.testing.expectError(error.UncompiledPresentation, walk.references(&validation, &references));
    const action = [_]compiler.Span{.{ .kind = .link, .text = "label", .target = "{{unresolved}}", .provenance = .protected_literal }};
    const action_blocks = [_]compiler.Block{.{ .kind = .paragraph, .spans = &action }};
    const action_refs = [_]compiler.Reference{.{ .number = 1, .group_number = 1, .blocks = &action_blocks }};
    var actions: CompilerWalk = .{};
    try std.testing.expectError(error.UncompiledTemplate, actions.references(&validation, &action_refs));
}

