    const reference_source = try std.mem.replaceOwned(u8, a, source, "gen<gène<genes: born of, produced by) >", "gen&lt;gène&lt;genes: born of, produced by) &gt;");
    try std.testing.expectEqual(source.len + 9, reference_source.len);
    var actual_report: Fallbacks = .{};
    var reference_report: Fallbacks = .{};
    const actual = try compileReportedWithLinkTrailAlloc(a, "මලදනු", .language, "සිංහල", "si", source, .{ .source = display, .page_title = "මලදනු" }, .{}, &namespaces, &actual_report);
    const expected = try compileReportedWithLinkTrailAlloc(a, "මලදනු", .language, "සිංහල", "si", reference_source, .{ .source = display, .page_title = "මලදනු" }, .{}, &namespaces, &reference_report);
    try std.testing.expectEqualSlices(u8, expected, actual);
    try std.testing.expect(actual_report.literal_markup);
    try std.testing.expect(!reference_report.literal_markup);
    var expected_report = reference_report;
    expected_report.literal_markup = true;
    try std.testing.expectEqualDeep(expected_report, actual_report);
    const stored = try codec.decodeAlloc(a, actual, "මලදනු", .language, .{ .code = "si", .heading = "සිංහල" });
    try std.testing.expectEqualSlices(u8, actual, try codec.encodeAlloc(a, stored));
    const headings = [_][]const u8{ "නිරුක්තිය", "උච්චාරණය", "නාම පදය", "අමතර අවධානයට", "මූලාශ්‍ර" };
    var found_headings: [headings.len]bool = @splat(false);
    const targets = [_][]const u8{ "ඔක්සිජන්", "අම්ලකර", "Oxygen", "දලදනු#සිංහල", "ද₂ම#සිංහල" };
    var found_targets: [targets.len]bool = @splat(false);
    var origin = false;
    var headword = false;
    var ipa = false;
    var reference_style = false;
    var pdf_action = false;
    for (stored.entry.sections) |section| {
        for (headings, 0..) |heading, i| {
            if (std.mem.eql(u8, section.title, heading)) {
                try std.testing.expect(!found_headings[i]);
                found_headings[i] = true;
            }
        }
        for (section.blocks) |block| {
            try std.testing.expect(block.table == null);
            var text: std.ArrayList(u8) = .empty;
            for (block.spans) |span| {
                if (span.kind == .line_break) try text.append(a, '\n') else try text.appendSlice(a, span.text);
                for (targets, 0..) |target, i| if (span.kind == .link and std.mem.eql(u8, span.target, target)) {
                    try std.testing.expect(!found_targets[i]);
                    found_targets[i] = true;
                };
                if (std.mem.eql(u8, span.text, "මලදනු") and span.bold and std.mem.eql(u8, span.language, "si"))
                    headword = true;
                if (std.mem.indexOf(u8, span.text, "/ˈmalədanu/") != null) {
                    ipa = true;
                    try std.testing.expect(std.mem.indexOf(u8, span.classes, "IPA") != null);
                }
                if (std.mem.indexOf(u8, span.text, "උරුමය") != null) {
                    reference_style = true;
                    try std.testing.expect(span.bold and span.italic);
                }
                if (span.kind == .external_link and std.mem.eql(u8, span.target, "https://www.ahubudu.lk/assets/pdf/EDIYA_Veluma5_Kalaba10.pdf")) {
                    try std.testing.expect(!pdf_action);
                    pdf_action = true;
                }
            }
            if (std.mem.indexOf(u8, text.items, "gen<gène<genes:") != null) {
                try std.testing.expect(!origin);
                origin = true;
                try std.testing.expectEqualStrings("මල (<අම්ල, oxy < oxys: sharp, acid) + දනු (gen<gène<genes: born of, produced by) > මලදනු.", std.mem.trimEnd(u8, text.items, " \t"));
            }
        }
    }
    for (found_headings) |found| try std.testing.expect(found);
    for (found_targets) |found| try std.testing.expect(found);
    try std.testing.expect(origin and headword and ipa and reference_style and pdf_action);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.references.len);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.media.len);
    const direct = [_]compiler.Span{.{ .text = "<genes: born of, produced by) >" }};
    const split = [_]compiler.Span{ .{ .text = "<gène", .provenance = .protected_literal }, .{ .text = "<genes:" }, .{ .text = " born of, produced by) >" } };
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &direct, null));
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &split, null));
    const unresolved = [_]compiler.Span{.{ .kind = .link, .text = "label", .target = "{{deferred}}", .provenance = .entity_literal }};
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, &unresolved, null));
}


test "cleaned invalid invoke title keeps literal source and valid actions through codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const broken_body = "antiquit\u{fffd}#Walon-Feller|antiquit\u{fffd}";
    const broken = "[[" ++ broken_body ++ "]]";
    const before = "=== Ortografeyes ===\n* ";
    const after = " ( [[(antikité#Walon-Feller|(antikité]] ) : ''upstream''\n* [[Good|label\u{fffd}]] [https://example.test/source source]\n";
    const source = before ++ broken ++ after;
    // Protect only the two authored delimiter pairs, retaining the ordinary
    // body parse and physical span boundaries used by the existing title path.
    const reference = before ++ "<nowiki>[[</nowiki>" ++ broken_body ++ "<nowiki>]]</nowiki>" ++ after;
    var report: Fallbacks = .{};
    const payload = try compileReportedAlloc(a, "antikité source-derived boundary", .supplemental, null, "", source, null, &report);
    const expected = try compileAlloc(a, "antikité source-derived boundary", .supplemental, null, "", reference, null);
    try std.testing.expectEqualSlices(u8, expected, payload);
    try std.testing.expect(report.literal_markup);
    try std.testing.expect(!report.missing_template);
    const stored = try codec.decodeAlloc(a, payload, "antikité source-derived boundary", .supplemental, null);
    const roundtrip = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualSlices(u8, payload, roundtrip);
    var actions: usize = 0;
    var literal_seen = false;
    var good_seen = false;
    var source_seen = false;
    var feller_seen = false;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        var visible: std.Io.Writer.Allocating = .init(a);
        defer visible.deinit();
        for (block.spans) |span| {
            try std.testing.expect(std.unicode.utf8ValidateSlice(span.text));
            try std.testing.expect(std.unicode.utf8ValidateSlice(span.trail));
            try std.testing.expect(std.unicode.utf8ValidateSlice(span.target));
            try visible.writer.writeAll(span.text);
            try visible.writer.writeAll(span.trail);
            if (span.kind == .link or span.kind == .external_link) {
                actions += 1;
                try std.testing.expect(std.mem.indexOf(u8, span.target, "\u{fffd}") == null);
                if (std.mem.eql(u8, span.target, "Good")) {
                    good_seen = true;
                    try std.testing.expectEqualStrings("label\u{fffd}", span.text);
                }
                source_seen = source_seen or std.mem.eql(u8, span.target, "https://example.test/source");
                feller_seen = feller_seen or std.mem.eql(u8, span.target, "(antikité#Walon-Feller");
            }
        }
        literal_seen = literal_seen or std.mem.indexOf(u8, visible.written(), broken) != null;
    };
    try std.testing.expectEqual(@as(usize, 3), actions);
    try std.testing.expect(literal_seen and good_seen and source_seen and feller_seen);
}

test "Danish localized POS organization keeps representative fire bodies identical to canonical POS codec controls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { owner: []const u8, code: []const u8, source: []const u8, kinds: []const []const u8, counts: []const usize };
    // Selected retained body witnesses and literal template-emitted headings;
    // these are organization/codec controls, not whole-page expansion or replay.
    const cases = [_]Case{
        .{ .owner = "dansk", .code = "da", .source = "==dansk==\n===Mængdetal===\n'''fire'''\n#''(mængdetal)'': [[4]]\n#*ordenstal: [[fjerde]]\nEksempler: En [[hund]] har fire ben.\n{| class=wikitable\n! Halve !! Dobbelte\n|-\n| 2 || 8\n|}\n====Oversættelser====\n* [[four]]\n===Verbum===\n'''fire'''\n# At [[sænke]] noget eller nogen ned;\n====Oversættelser====\n* [[mollir]]\n===Kilder===\nBibliography body.\n", .kinds = &.{ "Numeral", "Verb" }, .counts = &.{ 1, 1 } },
        .{ .owner = "engelsk", .code = "en", .source = "==engelsk==\n===Substantiv===\n'''fire'''\n# <span lang=da>[[ild#Dansk|ild]], [[bål#Dansk|bål]]</span>\n# <span lang=da>[[brand#Dansk|brand]]</span>\n# <span lang=da>[[flamme#Dansk|flamme]]</span>\n# <span lang=da>[[ild#Dansk|ild]], [[beskydning#Dansk|beskydning]]</span>\n# <span lang=da>[[ovn#Dansk|ovn]], [[ildsted#Dansk|ildsted]]</span>\n====Synonymer====\n* [[blaze]]\n* [[hold one's fire]]\n===Verbum===\n[malformed template]}\n# <span lang=da>[[skyde#Dansk|skyde]]</span>\n# <span lang=da>[[affyre#Dansk|affyre]]</span>\n# <span lang=da>[[fyre#Dansk|fyre]]</span>\n====Afledte termer====\n* [[fire away]]\n* [[fire at will]]\n* [[on fire]]\n* [[ready, aim, fire]]\n===Interjektion===\n'''fire'''\n# Dette ord mangler en definition. Hjælp gerne med at tilføje en definition.\n===Kilder===\nBibliography body.\n", .kinds = &.{ "Noun", "Verb", "Interjection" }, .counts = &.{ 5, 3, 1 } },
        .{ .owner = "norsk", .code = "no", .source = "==norsk==\n===Udtale===\n/ˇfiːrə/\n===Mængdetal===\n'''fire'''\n#''(mængdetal)'': [[#Dansk|fire]]\n#*ordenstal: [[fjerde]]\n===Kilder===\nBibliography body.\n", .kinds = &.{"Numeral"}, .counts = &.{1} },
    };
    for (cases) |case| {
        var reference = case.source;
        inline for (.{ .{ "===Mængdetal===", "===Numeral===" }, .{ "===Substantiv===", "===Noun===" }, .{ "===Verbum===", "===Verb===" }, .{ "===Interjektion===", "===Interjection===" } }) |mapping|
            reference = try std.mem.replaceOwned(u8, a, reference, mapping[0], mapping[1]);
        const bytes = try compileAlloc(a, "fire", .language, case.owner, case.code, case.source, null);
        const expected_bytes = try compileAlloc(a, "fire", .language, case.owner, case.code, reference, null);
        const stored = try codec.decodeAlloc(a, bytes, "fire", .language, .{ .heading = case.owner, .code = case.code });
        const expected = try codec.decodeAlloc(a, expected_bytes, "fire", .language, .{ .heading = case.owner, .code = case.code });
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        try std.testing.expectEqualDeep(expected.entry.organization, stored.entry.organization);
        try std.testing.expectEqual(case.kinds.len, stored.entry.organization.lexemes.len);
        for (stored.entry.organization.lexemes, case.kinds, case.counts) |lexeme, kind, count| {
            try std.testing.expectEqualStrings(kind, lexeme.kind);
            try std.testing.expectEqualStrings(case.owner, lexeme.language);
            try std.testing.expectEqual(count, lexeme.definitions.len);
            for (lexeme.definitions) |sense| {
                try std.testing.expect(sense.parent == null and sense.form == null);
                try std.testing.expect(stored.entry.sections[lexeme.section].blocks[sense.block].kind == .definition);
            }
        }
        try std.testing.expectEqual(expected.entry.sections.len, stored.entry.sections.len);
        for (stored.entry.sections, expected.entry.sections) |actual_section, expected_section| {
            try std.testing.expectEqual(actual_section.level, expected_section.level);
            try std.testing.expectEqualDeep(expected_section.blocks, actual_section.blocks);
        }
        try std.testing.expectEqualDeep(expected.entry.references, stored.entry.references);
        try std.testing.expectEqualDeep(expected.entry.media, stored.entry.media);
        try std.testing.expectEqualStrings(case.owner, stored.entry.language.?);
        try std.testing.expectEqualStrings(case.code, stored.entry.language_code);
    }
}

test "complete retained SL piacy gains owned verb sense without changing body report or codec" {
