test "IA both retained supplemental bodies preserve complete navigation lexical text and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { letter: u8, source: []const u8, bytes: usize, hash: []const u8 };
    for ([_]Case{
        .{ .letter = 'a', .source = iaRetainedA, .bytes = 3774, .hash = "a5738d4b058a08f4f46ac8b2f81f0057f4b6f15932cfd4f8f6d3489e6e91ee2b" },
        .{ .letter = 'l', .source = iaRetainedL, .bytes = 2367, .hash = "99b38af90e1e2c8d3fd79a561a86aa47974dbb1aefc52e66531b7337c0df5b1b" },
    }) |case| {
        try std.testing.expectEqual(case.bytes, case.source.len);
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(case.source, &digest, .{});
        try std.testing.expectEqualStrings(case.hash, &std.fmt.bytesToHex(digest, .lower));
        const title = try std.fmt.allocPrint(a, "Appendice:Dictionarios/Interlingua-catalano/{c}", .{case.letter});
        var reference = case.source;
        if (case.letter == 'l') {
            reference = try std.mem.replaceOwned(u8, a, reference, "<cf. lateral>", "&lt;cf. lateral>");
            reference = try std.mem.replaceOwned(u8, a, reference, "<cf. levogir>", "&lt;cf. levogir>");
        } else {
            reference = try std.mem.replaceOwned(u8, a, reference, "<adj., n.>", "&lt;adj., n.&gt;");
        }
        var report: Fallbacks = .{};
        const bytes = try compileReportedAlloc(a, title, .supplemental, null, "", case.source, null, &report);
        const expected = try compileAlloc(a, title, .supplemental, null, "", reference, null);
        // Complete payload equality covers all ordered sections, tables, spans,
        // flags, action targets, layout, references and media, not only anchors.
        try std.testing.expectEqualSlices(u8, expected, bytes);
        try std.testing.expect(report.literal_markup);
        const stored = try codec.decodeAlloc(a, bytes, title, .supplemental, null);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeBuildAlloc(a, stored.entry.display_title, stored.entry.sections, stored.entry.organization, stored.entry.references, stored.entry.media));
        const Witness = struct {
            a: A,
            letter: u8,
            text: std.ArrayList(u8) = .empty,
            letters: [26]std.ArrayList(u8) = @splat(.empty),
            anchors: [26]std.ArrayList(u8) = @splat(.empty),
            top: bool = false,
            parent: bool = false,
            bold_latere: bool = false,
            bold_leve: bool = false,
            bold_anglese: bool = false,
            fn spans(self: *@This(), values: []const types.Span) !void {
                for (values) |span| {
                    if (span.kind == .line_break) try self.text.append(self.a, '\n') else try self.text.appendSlice(self.a, span.text);
                    if (span.bold and std.mem.eql(u8, span.text, "latere")) self.bold_latere = true;
                    if (span.bold and std.mem.eql(u8, span.text, "leve")) self.bold_leve = true;
                    if (span.bold and std.mem.eql(u8, span.text, "anglese")) self.bold_anglese = true;
                    if (span.kind != .link) continue;
                    if (std.mem.eql(u8, span.target, "../")) self.parent = true;
                    if (std.mem.eql(u8, span.target, "#top")) {
                        try std.testing.expectEqualStrings("Capite", span.text);
                        self.top = true;
                    }
                    for (0..26) |index| {
                        const lower: u8 = @as(u8, @intCast(index)) + 'a';
                        const target = [_]u8{ '.', '.', '/', lower };
                        if (std.mem.eql(u8, span.target, &target)) {
                            try std.testing.expect(span.bold);
                            try self.letters[index].appendSlice(self.a, span.text);
                        }
                        const anchor = [_]u8{ '#', 'D', 'I', 'C', 'T', lower };
                        if (std.mem.eql(u8, span.target, &anchor)) {
                            try self.anchors[index].appendSlice(self.a, span.text);
                        }
                    }
                }
            }
            fn table(self: *@This(), value: types.Table) anyerror!void {
                try self.spans(value.caption);
                for (value.rows) |row| for (row.cells) |cell| {
                    if (cell.blocks) |ordered| try self.blocks(ordered) else {
                        try self.spans(cell.spans);
                        if (cell.nested_table) |nested| try self.table(nested);
                    }
                };
            }
            fn blocks(self: *@This(), values: []const types.Block) anyerror!void {
                for (values) |block| {
                    try self.spans(block.spans);
                    if (block.table) |value| try self.table(value);
                }
            }
        };
        var witness: Witness = .{ .a = a, .letter = case.letter };
        for (stored.entry.sections) |section| try witness.blocks(section.blocks);
        try std.testing.expect(witness.top and witness.parent);
        for (witness.letters, witness.anchors, 0..) |letter, anchor, index| {
            const lower: u8 = @as(u8, @intCast(index)) + 'a';
            const letter_label = [_]u8{ 0xc2, 0xa0, lower - 'a' + 'A', 0xc2, 0xa0 };
            const anchor_label = [_]u8{ case.letter, lower };
            try std.testing.expectEqualStrings(&letter_label, letter.items);
            try std.testing.expectEqualStrings(&anchor_label, anchor.items);
        }
        if (case.letter == 'l') {
            try std.testing.expect(witness.bold_latere and witness.bold_leve);
            try std.testing.expect(std.mem.indexOf(u8, witness.text.items, "latere costat <cf. lateral>") != null);
            try std.testing.expect(std.mem.indexOf(u8, witness.text.items, "leve esquerre <cf. levogir>; lleu") != null);
            try std.testing.expect(std.mem.indexOf(u8, witness.text.items, "Le Statos Unite de America Els Estats Units d’Amèrica") != null);
        } else {
            try std.testing.expect(witness.bold_anglese);
            try std.testing.expect(std.mem.indexOf(u8, witness.text.items, "anglese <adj., n.> anglès, -a") != null);
        }
    }
}

test "IA terminal dot suffix validation keeps raw action and template domains strict" {
    const a = std.testing.allocator;
    const raw = [_]compiler.Span{.{ .text = "<cf. lateral>" }};
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &raw, null));
    const adjacent = [_]compiler.Span{
        .{ .text = "<", .provenance = .protected_literal },
        .{ .text = "cf. lateral> [[" },
    };
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &adjacent, null));
    const target = [_]compiler.Span{.{ .text = "<", .kind = .link, .target = "{{unexpanded}}", .provenance = .protected_literal }};
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, &target, null));
    const label = [_]compiler.Span{.{ .text = "<cf. lateral>", .kind = .link, .target = "Target" }};
    try std.testing.expectError(error.UncompiledPresentation, validateSpans(a, &label, null));
}


const HySplitCloserBodyTest = struct {
    const targets = [_][]const u8{ "անգլերեն", "agravanman", "գերմաներեն", "դանիերեն", "էսպերանտո", "իսպաներեն", "իտալերեն", "հոլանդերեն", "հունարեն", "շվեդերեն", "պորտուգալերեն", "ռուսերեն", "վրացերեն", "ֆրանսերեն" };
    const Seen = struct {
        tables: usize = 0,
        table_actions: usize = 0,
        targets: [14]usize = @splat(0),
        quotation: bool = false,
        marked_word: bool = false,
        pronunciation: bool = false,
    };
    fn spans(seen: *Seen, values: []const types.Span, in_table: bool) void {
        for (values) |span| {
            if (std.mem.indexOf(u8, span.text, "Տեսավ նա նա այն ուղին") != null) seen.quotation = true;
            if (std.mem.eql(u8, span.text, "ամպրոպածեծ") and span.bold and span.background != null) seen.marked_word = true;
            if (std.mem.indexOf(u8, span.text, "ampropatsets") != null) seen.pronunciation = true;
            if (in_table and span.kind == .link) {
                seen.table_actions += 1;
                for (targets, 0..) |target, n| if (std.mem.eql(u8, span.target, target)) { seen.targets[n] += 1; };
            }
        }
    }
    fn table(seen: *Seen, value: types.Table) void {
        seen.tables += 1;
        spans(seen, value.caption, true);
        for (value.rows) |row| for (row.cells) |cell| {
            if (cell.blocks) |children| {
                blocks(seen, children, true);
            } else {
                spans(seen, cell.spans, true);
                if (cell.nested_table) |nested| table(seen, nested);
            }
        };
    }
    fn blocks(seen: *Seen, values: []const types.Block, in_table: bool) void {
        for (values) |block| {
            spans(seen, block.spans, in_table);
            if (block.table) |value| table(seen, value);
        }
    }
};

