test "retained SQ Common CSS preserves unrelated translation cell paint body actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const css = @embedFile("sq-common-css-profile.css");
    try std.testing.expectEqual(@as(usize, 13023), css.len);
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(css, &digest, .{});
    try std.testing.expectEqualStrings("dd1619c265c9860491cf7a93d53a0c397c328681caa4dd37660b33a58faac239", &std.fmt.bytesToHex(digest, .lower));
    // Complete authenticated Common.css, not a reduced selector fixture.
    // The body is a synthetic translation grid using the retained kre/mes
    // authored yellow-cell convention. No full SQ expansion is claimed.
    const unrelated_rule = ".Talk-Notice td {\n    background: inherit;\n}";
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, css, unrelated_rule));
    const reference_css = try std.mem.replaceOwned(u8, a, css, unrelated_rule, "");
    var profile = try @import("table_style_profile.zig").parseAlloc(a, css);
    defer profile.deinit();
    var reference_profile = try @import("table_style_profile.zig").parseAlloc(a, reference_css);
    defer reference_profile.deinit();
    const source = "==Translations==\nBefore '''grid''' [[Before]].\n{| border=0 width=100%\n|-\n|bgcolor=\"#FFFFE0\" valign=top width=20%|[[Alpha|first]]\n|}\n{| border=0 width=100%\n|-\n|bgcolor=\"#FFFFE0\" valign=top width=20%|''[[Beta|second]]''\n|\n|bgcolor=\"#FFFFE0\" valign=top width=20%|[[Gamma|third]]\n|\n|bgcolor=\"#FFFFE0\" valign=top width=20%|[https://example.test/fourth fourth]\n|}\nAfter [[After]].";
    const actual = try compileReportedWithOptionsAndPhasesAndTableStylesAlloc(a, "CSS fixture", .language, "Independent owner", "en", MissingText.untracked(source), null, .{}, null, null, null, null, null, &profile);
    const expected = try compileReportedWithOptionsAndPhasesAndTableStylesAlloc(a, "CSS fixture", .language, "Independent owner", "en", MissingText.untracked(source), null, .{}, null, null, null, null, null, &reference_profile);
    try std.testing.expectEqualSlices(u8, expected, actual);
    const stored = try codec.decodeAlloc(a, actual, "CSS fixture", .language, .{ .heading = "Independent owner", .code = "en" });
    try std.testing.expectEqualSlices(u8, actual, try codec.encodeAlloc(a, stored));
    try std.testing.expectEqualStrings("en", stored.entry.language_code);
    try std.testing.expectEqualStrings("Independent owner", stored.entry.language.?);
    var yellow: usize = 0;
    var tables: usize = 0;
    var actions: usize = 0;
    var italic = false;
    var fourth = false;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        if (block.table) |table| {
            tables += 1;
            for (table.rows) |row| for (row.cells) |cell| {
                if (cell.background) |background| {
                    try std.testing.expectEqualStrings("#ffffe0", background);
                    yellow += 1;
                }
                for (cell.spans) |span| {
                    if (span.kind == .link or span.kind == .external_link) actions += 1;
                    if (std.mem.eql(u8, span.target, "Beta")) {
                        try std.testing.expect(span.italic and std.mem.eql(u8, span.text, "second"));
                        italic = true;
                    }
                    if (std.mem.eql(u8, span.target, "https://example.test/fourth")) {
                        try std.testing.expect(span.kind == .external_link and std.mem.eql(u8, span.text, "fourth"));
                        fourth = true;
                    }
                }
            };
        } else for (block.spans) |span| if (span.kind == .link or span.kind == .external_link) { actions += 1; };
    };
    try std.testing.expectEqual(@as(usize, 2), tables);
    try std.testing.expectEqual(@as(usize, 4), yellow);
    try std.testing.expectEqual(@as(usize, 6), actions);
    try std.testing.expect(italic and fourth);
}

