    }
    const unresolved_target = [_]compiler.Span{.{ .kind = .link, .target = "{{missing}}", .text = "<", .provenance = .entity_literal }};
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, &unresolved_target, null));
