test "nonfloating image blocks preserve complete body actions cell ownership and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "==English==\n[[Before|before]][[File:Logo.svg|none|x40px|link=|alt=]][[After|after]]";
    // An independently authored block sequence uses the existing inline-image
    // representation on its own paragraph; none itself must not reach readers.
    const reference = "==English==\n[[Before|before]]\n\n[[File:Logo.svg|x40px|link=|alt=]]\n\n[[After|after]]";
    const bytes = try compileAlloc(a, "entry", .language, "English", "en", source, null);
    const reference_bytes = try compileAlloc(a, "entry", .language, "English", "en", reference, null);
    try std.testing.expectEqualSlices(u8, reference_bytes, bytes);
    const stored = try codec.decodeAlloc(a, bytes, "entry", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    var seen: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks, 0..) |value, index| for (value.spans) |span| if (span.image) |image| {
        seen += 1;
        try std.testing.expect(value.kind == .paragraph and value.list_path.len == 0);
        try std.testing.expectEqual(@as(usize, 1), value.spans.len);
        try std.testing.expect(index != 0 and index + 1 < section.blocks.len);
        try std.testing.expectEqualStrings("Before", section.blocks[index - 1].spans[0].target);
        try std.testing.expectEqualStrings("After", section.blocks[index + 1].spans[0].target);
        try std.testing.expectEqualStrings("Logo.svg", image.file);
        try std.testing.expectEqual(@as(?u32, null), image.width_px);
        try std.testing.expectEqual(@as(?u32, 40), image.height_px);
        try std.testing.expectEqualStrings("", image.alt.?);
        try std.testing.expect(image.tooltip == null);
        try std.testing.expect(span.kind == .text and span.target.len == 0 and span.text.len == 0 and span.trail.len == 0);
    };
    try std.testing.expectEqual(@as(usize, 1), seen);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.media.len);
    try std.testing.expectEqualStrings("Logo.svg", stored.entry.media[0].file);

    const cell_source = "==English==\n{| border=1\n| bgcolor=#abcdef | [[Before|before]][[File:Logo.svg|none|x40px|link=|alt=]][[After|after]]\n| neighbor\n|}\n# preserved meaning";
    const cell_bytes = try compileAlloc(a, "entry", .language, "English", "en", cell_source, null);
    const cell_stored = try codec.decodeAlloc(a, cell_bytes, "entry", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualSlices(u8, cell_bytes, try codec.encodeAlloc(a, cell_stored));
    var tables: usize = 0;
    var definitions: usize = 0;
    for (cell_stored.entry.sections) |section| for (section.blocks) |value| {
        if (value.kind == .definition) {
            definitions += 1;
            try std.testing.expectEqualStrings("#", value.list_path);
            try std.testing.expectEqualStrings("preserved meaning", value.spans[0].text);
        }
        if (value.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 2), table.rows[0].cells.len);
            const cell = table.rows[0].cells[0];
            try std.testing.expectEqualStrings("#abcdef", cell.background.?);
            try std.testing.expectEqual(@as(usize, 0), cell.spans.len);
            const blocks = cell.blocks orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(usize, 3), blocks.len);
            try std.testing.expectEqualStrings("Before", blocks[0].spans[0].target);
            try std.testing.expectEqualStrings("After", blocks[2].spans[0].target);
            try std.testing.expect(blocks[1].kind == .paragraph);
            try std.testing.expectEqual(@as(usize, 1), blocks[1].spans.len);
            const logo = blocks[1].spans[0];
            try std.testing.expectEqualStrings("Logo.svg", logo.image.?.file);
            try std.testing.expectEqual(@as(?u32, 40), logo.image.?.height_px);
            try std.testing.expectEqualStrings("", logo.image.?.alt.?);
            try std.testing.expect(logo.kind == .text and logo.target.len == 0);
            try std.testing.expectEqualStrings("neighbor", std.mem.trim(u8, table.rows[0].cells[1].spans[0].text, " \t\r\n"));
        }
    };
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expectEqual(@as(usize, 1), definitions);
}

test "literal query targets require exact parsed source proof through validation and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const url = "http://example.test/path?l={{{1}}}&lang=grc#lexicon";
    const source = "[" ++ url ++ " " ++ url ++ "]";
    var renderer: compiler.Renderer = .{ .a = a, .context = .{} };
    const spans = try renderer.parseSpans(source, .{});
    var report: Fallbacks = .{};
    try validateSpans(a, spans, &report);
    const copied = try a.dupe(compiler.Span, spans);
    for (copied) |*span| span.target = try a.dupe(u8, span.target);
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, copied, &report));
    for ([_]compiler.Provenance{ .parsed, .protected_literal, .entity_literal }) |origin| {
        const forged = [_]compiler.Span{.{ .kind = .external_link, .text = "label", .target = url, .provenance = origin, .flags = .{ .code = true } }};
        try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, &forged, &report));
    }
    // A proof for one complete token cannot authorize any other destination.
    const wrong = try a.dupe(compiler.Span, spans);
    for (wrong) |*span| span.target = "http://example.test/path?l={{missing}}";
    try std.testing.expectError(error.UncompiledTemplate, validateSpans(a, wrong, &report));
    var fallbacks: Fallbacks = .{};
    const payload = try compileReportedAlloc(a, "query literal", .language, "Greek", "grc", source, null, &fallbacks);
    const stored = try codec.decodeAlloc(a, payload, "query literal", .language, .{ .heading = "Greek", .code = "grc" });
    var visible: std.ArrayList(u8) = .empty;
    var actions: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        try visible.appendSlice(a, span.text);
        if (span.kind == .external_link) {
            actions += 1;
            try std.testing.expectEqualStrings(url, span.target);
        }
    };
    try std.testing.expect(actions != 0);
    try std.testing.expectEqualStrings(url, visible.items);
    try std.testing.expect(fallbacks.missing_template);
    // The borrowed source-token proof is compiler state, never shipped data.
    try std.testing.expect(std.mem.indexOf(u8, payload, source) == null);
    try std.testing.expectEqualSlices(u8, payload, try codec.encodeAlloc(a, stored));
}

test "class-hidden rows preserve complete compiled body references media and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var profile = try @import("table_style_profile.zig").parseAlloc(a, ".omit { display:none; }");
    defer profile.deinit();
    const source = "==English==\n===Noun===\n# visible meaning [[Sense|action]]\n" ++
        "{|\n| first\n|- class=omit\n| <ref name=hidden>hidden definition [[Citation|source]]</ref>\n" ++
        "{|\n| [[Hidden|invisible]]<ref>hidden anonymous</ref>[[File:Hidden.svg|15px|link=HiddenAsset]]\n|}\n" ++
        "|-\n| kept<ref name=hidden/><ref>visible note</ref> [[Visible|visible]]\n|}\n<references/>";
    const inline_source = try std.mem.replaceOwned(u8, a, source, "|- class=omit", "|- class=omit style='display:none!important'");
    var reported: Fallbacks = .{};
    var inline_report: Fallbacks = .{};
    const bytes = try compileReportedWithOptionsAndPhasesAndTableStylesAlloc(a, "scope", .language, "English", "en", MissingText.untracked(source), null, .{}, null, null, null, &reported, null, &profile);
    const inline_bytes = try compileReportedWithOptionsAndPhasesAndTableStylesAlloc(a, "scope", .language, "English", "en", MissingText.untracked(inline_source), null, .{}, null, null, null, &inline_report, null, &profile);
    // Compare every serialized body/style/action/reference/media/organization
    // field against the already supported explicit-inline visibility path.
    try std.testing.expectEqualSlices(u8, inline_bytes, bytes);
    const stored = try codec.decodeAlloc(a, bytes, "scope", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    try std.testing.expectEqual(@as(usize, 3), stored.entry.references.len);
    try std.testing.expectEqualStrings("hidden", stored.entry.references[0].name);
    var tables: usize = 0;
    var visible_actions: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| if (block.table) |table| {
        tables += 1;
        try std.testing.expectEqual(@as(usize, 2), table.rows.len);
        for (table.rows) |row| for (row.cells) |cell| for (cell.spans) |span| {
            try std.testing.expect(span.image == null);
            try std.testing.expect(!std.mem.eql(u8, span.target, "Hidden") and !std.mem.eql(u8, span.target, "HiddenAsset"));
            if (std.mem.eql(u8, span.target, "Visible")) visible_actions += 1;
        };
    };
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expectEqual(@as(usize, 1), visible_actions);
    try std.testing.expect(!reported.unsupported_element and !reported.malformed_table);
}

